window.ayetHadisData = {"ayetler":[{"metin":"Kur’ân-ı kerîm okuyacağın zemân E’ûzü... söyle","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":3},{"metin":"Ni’metlerimin kıymetini bilir, şükr ederseniz, ya’nî emr etdiğim gibi kullanırsanız, onları artdırırım. Kıymetlerini bilmez, bunları beğenmezseniz, elinizden alır, şiddetli azâb ederim","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":6},{"metin":"Ey sevgili Peygamberim “sallallahü aleyhi ve sellem”! Seni, dünyâdaki bütün insanlara ebedî se’âdeti müjdelemek ve bu se’âdet yolunu göstermek için, beşeriyyete gönderiyorum","sure":null,"ayet_no":null,"kisim":1,"madde":1,"sayfa":20},{"metin":"Ey sevgili Peygamberim “sallallahü aleyhi ve sellem”! Onlara de ki, eğer Allahü teâlâyı seviyorsanız ve Allahü teâlânın da, sizi sevmesini istiyorsanız, bana tâbi’ olunuz! Allahü teâlâ bana tâbi’ olanları sever","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":21},{"metin":"Elbette muhakkak böyledir","sure":"Nisâ","ayet_no":"sekseninci","kisim":1,"madde":2,"sayfa":21},{"metin":"Kâfirler, Allahü teâlânın emrleri ile Peygamberlerinin emrlerini birbirinden ayırmak istiyorlar. Yehûdîler diyor ki, biz Mûsâ aleyhisselâma inanırız. Îsâ ile Muhammed aleyhimesselâma inanmayız. Hıristiyanlar ise, yalnız Îsâ aleyhisselâma inanıp, Ona, hâşâ, Allahü teâlânın oğlu diyor. Bu inanışları ve dinleri kıymetsizdir. Onların hepsi kâfirdir. Kâfirlerin hepsine Cehennem azâbını, çok acı azâbları hâzırladık","sure":"Nisâ","ayet_no":"yüzellinci ve yüzellibirinci","kisim":1,"madde":2,"sayfa":21},{"metin":"Câhiller, ahmaklar, dünyâdaki zevk ve lezzetlere kavuşmak için, dinlerini, îmânlarını verdi. Âhıretlerini satıp, dünyâyı, şehvetlerinin istediklerini aldılar. Kurtuluş yolunu bırakıp, helâke koşdular. Bu alış verişlerinde birşey kazanmadılar. Bunlar, ticâret ve kazanç yolunu bilmedi. Çok ziyân etdi","sure":"Bekara","ayet_no":null,"kisim":1,"madde":8,"sayfa":23},{"metin":"Ey benim sevgili Peygamberime “sallallahü aleyhi ve sellem” inananlar! Eğer, kâfirlerin sözlerine aldanıp da, Resûlümün “sallallahü aleyhi ve sellem” yolundan ayrılırsanız, kendilerine müslimân süsü veren din düşmanlarının, ya’ni zındıkların uydurma ve yaldızlı sözlerine kapılarak, îmânınızı çaldırırsanız, dünyâda ve âhıretde ziyân edersiniz","sure":"İmrân","ayet_no":null,"kisim":1,"madde":11,"sayfa":24},{"metin":"Nûh aleyhisselâma inanmadılar. Onları suda boğduk. Ondan sonra yaratdığımız insanlara, içlerinden Peygamber gönderdik ve Allahü teâlâya ibâdet ediniz. İbâdet edilecek, Ondan başkası yokdur. Onun azâbından korkunuz! dedik. Dinlemiyenlerden, öldükden sonra tekrâr dirilmeğe inanmıyanlardan, dünyâ ni’metlerini bol bol vermiş olduğumuz birçoğu, bu Peygamber, sizin gibi yiyip içiyor. Kendiniz gibi bir çok şeye muhtâc olan birine inanırsanız, aldanmış, ziyân etmiş olursunuz. Peygamber, size ölüp, kemikleriniz çürüyüp, toz toprak oldukdan sonra, tekrâr dirilerek kabrden kalkacaksınız diyor. Hiç böyle şey olur mu? Ne varsa, ancak bu dünyâdadır. Cennet, Cehennem, hep buradadır. Bu dünyâ böyle gelmiş böyle gider. Öldükden sonra, bir dahâ dirilmek yokdur, dediler","sure":null,"ayet_no":null,"kisim":1,"madde":11,"sayfa":26},{"metin":"Bu düşmanların düâları netîcesizdir. Kabûl olmak ihtimâli yokdur","sure":"Tevbe","ayet_no":"yirmisekizinci","kisim":1,"madde":11,"sayfa":29},{"metin":"Allahü teâlâ, kullarına zulm etmez, haksızlık etmez. Onlar, kendilerini azâba, acılara sürükleyen bozuk düşünceleri, çirkin işleri ile kendilerine zulm ve işkence ediyorlar","sure":"Nahl","ayet_no":"otuzüçüncü","kisim":1,"madde":12,"sayfa":30},{"metin":"Kâfirler, mal ve çok evlâd gibi dünyâlıkları verdiğimiz için, kendilerine iyilik mi ediyoruz, yardım mı ediyoruz sanıyor. Peygamberime “sallallahü aleyhi ve sellem” inanmadıkları ve dîn-i islâmı beğenmedikleri için, onlara mükâfât mı ediyoruz, diyorlar? Hayır öyle değildir. Aldanıyorlar. Bunların ni’met olmayıp, musîbet olduğunu anlamıyorlar","sure":null,"ayet_no":null,"kisim":1,"madde":13,"sayfa":31},{"metin":"Görüşleri kısa, aklları eksik olanlar, âhıreti düşünmeyip her iyiliği, şöhret, mevkı’ ve hurmet gibi dünyâ râhatlıklarını ve lezzetlerini kazanmak için yapıyor. Bu yapdıklarının karşılıklarını dünyâda kendilerine temâmen verir, umduklarından birini esirgemeyiz. Bunların âhıretdeki kazançları, yalnız Cehennem ateşidir. Çünki, iyiliklerinin karşılıklarını almışlardır. Alacakları yalnız, bozuk niyyetlerinin karşılığı olan, Cehennem ateşi kalmışdır. Hırs ve şehvetleri için, gösteriş için yapdıkları iyilikleri âhıretde kendilerine yaramıyacak, bunları Cehennemden kurtaramıyacakdır","sure":"Hûd","ayet_no":"onbeşinci","kisim":1,"madde":14,"sayfa":32},{"metin":"Görüşleri ve aklları, bu dünyâ çerçevesine sıkışmış olanlar, âhıreti bırakarak dünyânın çabuk geçici zevklerinin arkasında koşuyor. Gece gündüz düşündükleri ve sıkıntılara katlanarak özledikleri bu ni’metlerden, dilediğimizi, istediklerimize kolaylıkla ve bol bol veririz. Fekat, bunlara böylece iyilik etmiyoruz. Cehennem azâbını hâzırlıyoruz. Bunlar âhıretde rahmetden uzaklaşdırılıp, kötü bir hâlde, Cehenneme sürükleneceklerdir. Herbiri çabuk biten ve arkasından sıkıntılar ve felâketler bırakan bu dünyâ lezzetlerine bağlanmayıp da, va’d etdiğim sonsuz ve hakîkî ve hiç değişmeyen âhıret ni’metlerini istiyerek, gösterdiğim ve beğendiğim iyilikleri yapanlara gelince, bunlar, Kur’ân-ı kerîmde bildirdiğim yolda yürüdükleri için, bütün iyiliklerini beğeniriz. Dünyâda, hem dünyânın âşıklarına, hem de sözlerime inanıp emrlerimi yapanlara istediklerini veririz. Kimseyi umduğundan mahrûm bırakmayız. Ni’metlerimizi hepsine serperiz. Senin Rabbinin ni’metlerinin yetişmediği kimse yokdur","sure":"Hûd","ayet_no":"onbeşinci","kisim":1,"madde":14,"sayfa":32},{"metin":"Allahü teâlâya ve kıyâmet gününe îmân edenler, Allahü teâlânın ve resûlünün düşmanlarını sevmezler. O kâfirler ve münâfıklar, mü’minlerin anaları, babaları, oğulları, kardeşleri ve başka yakınları olsa da, bunları sevmezler. Böyle olan mü’minleri Cennete koyacağım","sure":"Mücâdele","ayet_no":"son","kisim":1,"madde":19,"sayfa":38},{"metin":"Kâfirlerin hücûm ve işkencelerine uğramamak, onları da, se’âdet-i ebediyyeye kavuşdurmak için, insan gücünün yetdiği kadar durmadan çalışınız. En mükemmel harb vâsıtalarını yapınız!","sure":"Enfâl","ayet_no":"altmışıncı","kisim":1,"madde":20,"sayfa":39},{"metin":"Kâfirlerin câmi’ yapmaları câiz değildir. Yerinde ve yarar bir iş değildir. Onların câmi’ yapmaları ve diğer bütün beğendikleri işleri, kıyâmetde kendilerine yaramıyacak ve Muhammed aleyhisselâma tâbi’ olmadıkları için, Cehenneme girip, çok acı azâblarda sonsuz olarak cezâlandırılacaklardır","sure":"Tevbe","ayet_no":"onsekizinci","kisim":1,"madde":21,"sayfa":40},{"metin":"Muhammed aleyhisselâmın getirdiği İslâm dîninden başka din istiyenlerin, dinlerini Allahü teâlâ sevmez ve kabûl etmez. Dîn-i islâma arka çeviren, âhıretde ziyân edecek, Cehenneme girecekdir","sure":"İmrân","ayet_no":"seksenbeşinci","kisim":1,"madde":21,"sayfa":40},{"metin":"Allahü teâlânın ve Peygamberi Muhammed aleyhisselâmın emrlerine aldırış etmiyenler, beğenmiyenler, asra, fenne uygun değildir, modern ihtiyâclara kâfi değildir diyenler, kıyâmetde Cehennem ateşinden kurtulamıyacaklardır. Bunlara, Cehennemde, çok acı azâb vardır","sure":"Nisâ","ayet_no":"onüçüncü","kisim":1,"madde":21,"sayfa":40},{"metin":"Muhammed aleyhisselâma inanıp, âhırete yarayan işleri yapanlara [ya’nî ahkâm-ı islâmiyyeye uyanlara], Allahü teâlâ, va’d etdiklerini verecek ve ayrıca çok ihsân yapacakdır. Allahü teâlâya ibâdet etmeği, ya’nî Muhammed aleyhisselâma itâ’at etmeği, aşağılık, gericilik sanıp, kendilerine asrî ve münevver diyerek, büyüklük taslıyanlara, çok azâb edecekdir. Kendilerini herkesin üstünde sanan bu kâfirleri, Cehennemden kurtaracak bir yardımcı, Allahü teâlâdan başka bir kuvvet sâhibi bulunmıyacakdır","sure":"Nisâ","ayet_no":"yüzyetmişikinci","kisim":1,"madde":21,"sayfa":40},{"metin":"Sizden evvel gelip geçenlerin hayâtlarını, gitdikleri yolları ve başlarına gelenleri, gözden geçirip, onlardan ders alınız. Yerleri, gökleri, canlıları, cansızları ve kendinizi inceleyiniz! Gördüklerinizin içini, özünü araşdırınız. Bütün bunlarda yerleşdirmiş olduğum kuvvetimi, kudretimi, büyüklüğümü ve hâkimiyyetimi bulunuz, görünüz, anlayınız!","sure":null,"ayet_no":null,"kisim":1,"madde":24,"sayfa":42},{"metin":"Kur’ân-ı kerîm gibi ilâhî belâgat ve îcâzı hâiz bir kitâb, yalnız türkçeye değil, hiçbir dile hakkıyle çevrilemez. Eski tefsîrlerin ışığı altında verilen ma’nâlara da terceme değil, meâl demek uygundur. Kur’ânın yalnız ma’nâsını ifâde eden sözleri, Kur’ân hükmünde tutmak, nemâzda okumak ve aslına hakkıyle vâkıf olunmadan ahkâm çıkarmak câiz olmaz. Hiçbir terceme, aslının yerini tutamaz. Kur’ân-ı kerîmde, muhtelif ma’nâlara gelen lafzlar vardır. Böyle bir lafzı terceme etmek, çeşidli ma’nâlarını bire indirmek olur ki, verilen tek ma’nânın, murâd-ı ilâhî olduğu bilinemez. Bunun için, Kur’ân tercemesi demeğe cesâret edilemez. Kur’ân-ı kerîmi terceme etmek başka, tercemeyi Kur’ân yerine koymağa kalkışmak başkadır","sure":null,"ayet_no":null,"kisim":1,"madde":25,"sayfa":46},{"metin":"Benim kitâbım arabîdir","sure":null,"ayet_no":null,"kisim":1,"madde":25,"sayfa":47},{"metin":"Muhammed aleyhisselâma, bu Kur’ânı arabî dil ile indirdim","sure":null,"ayet_no":null,"kisim":1,"madde":25,"sayfa":47},{"metin":"Allahü teâlâ sizlere hafîf, kolay emr etmek istiyor. İnsanlar, za’îf, kuvveti az yaratılmışdır","sure":null,"ayet_no":null,"kisim":1,"madde":31,"sayfa":57},{"metin":"Allahü teâlâ, size kolay olan şeyleri yapdırmak istiyor, güç olanı istemiyor","sure":"Bekara","ayet_no":"yüzseksenbeşinci","kisim":1,"madde":35,"sayfa":71},{"metin":"Allahü teâlâ, ibâdetlerinizin hafîf, kolay olmasını istiyor. İnsan za’îf, dayanıksız yaratıldı","sure":"Nisâ","ayet_no":"yirmisekizinci","kisim":1,"madde":35,"sayfa":71},{"metin":"Rabbinin rızâsına kavuşmak istiyen için, bu elbette bir nasîhatdir","sure":"Müzzemmil","ayet_no":"ondokuzuncu","kisim":1,"madde":37,"sayfa":78},{"metin":"Rabbiniz Erdı sizin için, yatak gibi döşedi","sure":null,"ayet_no":null,"kisim":1,"madde":39,"sayfa":82},{"metin":"Erdın sizi sarsmaması için, üzerinde dağlar döşedim","sure":"Nahl","ayet_no":"onbeşinci","kisim":1,"madde":39,"sayfa":82},{"metin":"Allah, Erdı size karâr yapdı","sure":"Nahl","ayet_no":"onbeşinci","kisim":1,"madde":39,"sayfa":82},{"metin":"Allahü teâlâ için misâller getirmeyin","sure":"Nahl","ayet_no":null,"kisim":1,"madde":39,"sayfa":86},{"metin":"Allahü teâlâ, insan ölürken rûhunu bedeninden ayırır. Ölmediği zemân, uykuda da, rûhunu ayırır","sure":"Zümer","ayet_no":"kırkikinci","kisim":1,"madde":40,"sayfa":88},{"metin":"Zulm edenlere ve etmiyenlere birlikde gelen fitne ve belâdan korkunuz, sakınınız","sure":"Enfâl","ayet_no":"yirmibeşinci","kisim":1,"madde":41,"sayfa":90},{"metin":"Ey îmân eden kullarım! Kendinize dikkat ediniz! Doğru yolu bulursanız, başkasının sapıtması size zarar vermez","sure":"Mâide","ayet_no":"yüzsekizinci","kisim":1,"madde":41,"sayfa":94},{"metin":"Ey mü’min kullarım! Emr etdiğim işleri, ibâdetleri yapar ve emr-i ma’rûf ve nehy-i münker eder iseniz, başkalarının yoldan çıkması, size zarar vermez","sure":"Mâide","ayet_no":"yüzsekizinci","kisim":1,"madde":41,"sayfa":94},{"metin":"Ey mü’minler! Hepiniz, Allahü teâlâya tevbe ediniz! Tevbe etmekle kurtulabilirsiniz","sure":"Nûr","ayet_no":"otuzbirinci","kisim":1,"madde":43,"sayfa":97},{"metin":"Ey îmân eden seçilmişler! Allahü teâlâya dönünüz! Hâlis tevbe edin! Ya’nî tevbenizi bozmayın! Böyle tevbe edince, Rabbiniz, sizi belki afv eder ve ağaçlarının, köşklerinin altından [önünden] sular akan Cennetlere sokar","sure":"Tahrîm","ayet_no":"sekizinci","kisim":1,"madde":43,"sayfa":97},{"metin":"Açık olsun, gizli olsun günâhlardan sakınınız!","sure":"Tahrîm","ayet_no":"sekizinci","kisim":1,"madde":43,"sayfa":97},{"metin":"Fir’avn dedi ki: Bizden evvel gelip geçenlerin hâlleri ne oldu?","sure":null,"ayet_no":null,"kisim":1,"madde":46,"sayfa":105},{"metin":"Mallarını, canlarını fedâ ederek din düşmanları ile, Allah rızâsı için cihâd eden müslimânlar, oturup, ibâdet edenlerden dahâ üstündür. Hepsine de, Cenneti söz veriyorum","sure":"Nisâ","ayet_no":"doksandördüncü","kisim":1,"madde":46,"sayfa":107},{"metin":"Resûlümün “sallallahü aleyhi ve sellem” getirdiklerini alınız!","sure":"Haşr","ayet_no":"yedinci","kisim":1,"madde":46,"sayfa":107},{"metin":"Ey îmân edenler, kendinizi ve çoluk çocuğunuzu öyle bir ateşden koruyun ki, onun tutuşdurucusu insanlarla taşlardır","sure":"Tahrîm","ayet_no":"altıncı","kisim":1,"madde":46,"sayfa":112},{"metin":"Her nemâzı kılarken süslü, temiz, sevilen elbiselerinizi giyiniz!","sure":null,"ayet_no":null,"kisim":1,"madde":46,"sayfa":112},{"metin":"Yeri iki günde yaratdı","sure":null,"ayet_no":null,"kisim":1,"madde":48,"sayfa":116},{"metin":"Sonra, yedi gökü de iki günde var eyledi","sure":null,"ayet_no":null,"kisim":1,"madde":48,"sayfa":116},{"metin":"Sûra bir kerre üfürülünce, yeryüzü ve dağlar, yerlerinden kaldırılıp silkilecekdir. O gün kıyâmet kopacak, gök yarılacak ve dağılacakdır","sure":null,"ayet_no":null,"kisim":1,"madde":49,"sayfa":117},{"metin":"Güneşin karardığı, yıldızların yerlerinden ayrılıp döküldükleri ve dağların dağılıp saçıldıkları zemâna...","sure":null,"ayet_no":null,"kisim":1,"madde":49,"sayfa":117},{"metin":"Gökün yarıldığı ve yıldızların dağılıp yok oldukları zemân...","sure":null,"ayet_no":null,"kisim":1,"madde":49,"sayfa":117},{"metin":"Herşey yok olacakdır. Yalnız O kalacakdır!","sure":null,"ayet_no":null,"kisim":1,"madde":49,"sayfa":117},{"metin":"Ni’metlerime şükr ederseniz, onları artdırırım","sure":null,"ayet_no":null,"kisim":1,"madde":50,"sayfa":118},{"metin":"Bir işde anlaşamazsanız, bu işin hükmünü Allahdan ve Resûlullahdan anlayınız!","sure":"Nisâ","ayet_no":null,"kisim":1,"madde":50,"sayfa":120},{"metin":"Ey îmân etmekle şereflenen kullarım! Cum’a günü, öğle ezânı okunduğu zemân, hutbe dinlemek ve Cum’a nemâzı kılmak için câmi’e koşunuz. Alış verişi bırakınız! Cum’a nemâzı ve hutbe, size, başka işlerinizden dahâ fâidelidir. Cum’a nemâzını kıldıkdan sonra, câmi’den çıkar, dünyâ işlerinizi yapmak için dağılabilirsiniz. Allahü teâlâdan rızk bekliyerek çalışırsınız. Allahü teâlâyı çok hâtırlayınız ki, kurtulabilesiniz!","sure":null,"ayet_no":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Allah, fâiz ile elde edilenleri yok eder. İzlerini bile bırakmaz. Zekâtları verilen malları artdırır","sure":"Bekara","ayet_no":"ikiyüzyetmişbeşinci","kisim":1,"madde":78,"sayfa":302},{"metin":"Allahü teâlânın ihsân etdiği malın zekâtını vermeyenler, iyi etdiklerini, zengin kalacaklarını sanıyor. Hâlbuki, kendilerine kötülük yapmış oluyorlar. O malları, Cehennemde azâb âleti olacak, yılan şeklinde boyunlarına sarılıp, başdan ayağa kadar onları sokacakdır","sure":"Haşr","ayet_no":"dokuzuncu","kisim":1,"madde":78,"sayfa":311},{"metin":"Beyâz iplik siyâhdan ayırd edilinceye kadar yiyiniz, içiniz!","sure":"Bekara","ayet_no":null,"kisim":1,"madde":79,"sayfa":316},{"metin":"Adaklarını yerine getirsinler!","sure":"Hac","ayet_no":"yirmidokuzuncu","kisim":1,"madde":82,"sayfa":331},{"metin":"Sen güzel huylu olarak yaratıldın","sure":null,"ayet_no":null,"kisim":1,"madde":96,"sayfa":383},{"metin":"Seni, âlemlere rahmet, iyilik için gönderdik","sure":"Enbiyâ","ayet_no":"yüzyedinci","kisim":1,"madde":96,"sayfa":383},{"metin":"Sen, ya’nî Senin nûrun, hep secde edenlerden dolaşdırılıp, sana inkılâb etmiş, ulaşmışdır","sure":null,"ayet_no":null,"kisim":1,"madde":97,"sayfa":387},{"metin":"Baban İbrâhîmin ve İsmâ’îlin Rabbi","sure":null,"ayet_no":null,"kisim":1,"madde":97,"sayfa":390},{"metin":"Bana ibâdet yapmak istemiyenleri, zelîl ve hakîr yapar, Cehenneme atarım","sure":null,"ayet_no":null,"kisim":1,"madde":98,"sayfa":395},{"metin":"Yardım, ancak ve yalnız Allahdandır","sure":"İmrân","ayet_no":"yüzyirmialtıncı","kisim":2,"madde":2,"sayfa":400},{"metin":"Peygamberlerden Ulül’azm olanların sabr etdikleri gibi Sen de sabr et! Onlara azâb verilmesi için düâ etmekde acele eyleme!","sure":"Ahkâf","ayet_no":null,"kisim":2,"madde":9,"sayfa":426},{"metin":"Şeytân insana çok şeyi sözverir ve birçok şeyi hâtırlatır. Şeytânın sözverdiği şeylerin hepsi yalandır","sure":"Nisâ","ayet_no":"yüzyirminci","kisim":2,"madde":13,"sayfa":428},{"metin":"Şeytânın aldatması, elbette za’îfdir","sure":"Nisâ","ayet_no":"yetmişaltıncı","kisim":2,"madde":13,"sayfa":428},{"metin":"İnsanlar mı bize doğru yol gösterecekler dediler. Böylece kâfir oldular","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":429},{"metin":"Şükr ederseniz, ni’metimi artdırırım!","sure":"İbrâhîm","ayet_no":"yedinci","kisim":2,"madde":14,"sayfa":429},{"metin":"Benim ismim Allahdır. Beni Allah diye çağırınız. Allah diye ibâdet ediniz. Allah diye yalvarınız!","sure":null,"ayet_no":null,"kisim":2,"madde":15,"sayfa":431},{"metin":"Muhâcirînin ve Ensârın önce olanları ve bunlara tâbi’ olanlar, Allahü teâlâdan râzıdır. Allahü teâlâ da onlardan râzıdır. Onlara Cennetleri hâzırladım. Burada sonsuz kalacaklardır","sure":null,"ayet_no":null,"kisim":2,"madde":16,"sayfa":445},{"metin":"Allahü teâlâ, gaybdan bildiği şeylerden ba’zılarını yalnız Peygamberlerden dilediğine bildirir","sure":"Cin","ayet_no":"yirmialtıncı","kisim":2,"madde":17,"sayfa":448},{"metin":"Ancak Onun izn vermesi ile şefâ’at olunur","sure":null,"ayet_no":null,"kisim":2,"madde":17,"sayfa":451},{"metin":"Ancak râzı olunan kimselere şefâ’at olunur","sure":null,"ayet_no":null,"kisim":2,"madde":17,"sayfa":451},{"metin":"Allah yolunda öldürülenlere ölü demeyiniz! Onlar diridir. Fekat, siz bunu anlamıyorsunuz","sure":"Bekara","ayet_no":null,"kisim":2,"madde":17,"sayfa":460},{"metin":"Ey îmân edenler! Allahın dînine sarılınız. Birbirinizden ayrılmayınız!","sure":"İmrân","ayet_no":null,"kisim":2,"madde":17,"sayfa":464},{"metin":"Allahü teâlâya yaklaşmak için, vesîle arayınız!","sure":"Mâide","ayet_no":"otuzbeşinci","kisim":2,"madde":17,"sayfa":466},{"metin":"Bilmediklerinizi, bilenlerden sorup öğreniniz!","sure":"Mâide","ayet_no":"otuzbeşinci","kisim":2,"madde":17,"sayfa":466},{"metin":"Sen öleceksin. O kâfirler de ölecekler. Sonra, kıyâmet günü, Rabbinizin huzûrunda hesâblaşacaksınız. Senin haklı olduğun, müşriklerin, bâtıl, bozuk olduğu meydâna çıkacak","sure":"Zümer","ayet_no":"otuzuncu","kisim":2,"madde":18,"sayfa":475},{"metin":"Kâfirlere atdığını sen atmadın, onları Allahü teâlâ atdı","sure":"Enfâl","ayet_no":"onyedinci","kisim":2,"madde":18,"sayfa":478},{"metin":"Ey insan! Sana gelen her iyilik, Allahü teâlânın ihsânı olarak, ni’meti olarak gelmekdedir. Her derd ve belâ da, kötülüklerine karşılık olarak gelmekdedir. Hepsini yaratan, gönderen Allahü teâlâdır","sure":"Nisâ","ayet_no":"yetmişsekizinci","kisim":2,"madde":18,"sayfa":479},{"metin":"Bana itâ’at etmek isteyen, Resûlüme itâ’at etsin!","sure":null,"ayet_no":null,"kisim":2,"madde":18,"sayfa":479},{"metin":"Biz, Peygamber göndererek bildirmeden önce, azâb yapıcı değiliz","sure":"İsrâ","ayet_no":"onbeşinci","kisim":2,"madde":20,"sayfa":481},{"metin":"Peygamberleri, müjde vermek için ve korkutmak için gönderdim. Böylece, insanların Allahü teâlâya özr, behâne yapmaları önlendi","sure":"Nisâ","ayet_no":"yüzaltmışdördüncü","kisim":2,"madde":20,"sayfa":481},{"metin":"İyi biliniz ki, kalbler, Allahü teâlânın zikri ile itminâna, râhata kavuşur!","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":482},{"metin":"O, boşuna konuşmaz. Hep, vahy olunanı söylemekdedir","sure":null,"ayet_no":null,"kisim":2,"madde":23,"sayfa":505},{"metin":"Allahü teâlânın gönderdiğine uymıyanlar kâfirdir","sure":"Mâide","ayet_no":"kırkdördüncü","kisim":2,"madde":23,"sayfa":505},{"metin":"Ey Peygamberim “aleyhisselâm”! Sana, Allah ve mü’minlerden, senin izinde gidenler yetişir!","sure":"Enfâl","ayet_no":"altmışdördüncü","kisim":2,"madde":23,"sayfa":505},{"metin":"O, boş söz söylemez!","sure":null,"ayet_no":null,"kisim":2,"madde":23,"sayfa":505},{"metin":"Onlara izn verdiğin için olan hatânı, Allahü teâlâ afv etdi","sure":"Tevbe","ayet_no":"kırküçüncü","kisim":2,"madde":23,"sayfa":505},{"metin":"Ey akl sâhibleri, başkalarından ibret alınız!","sure":"Haşr","ayet_no":"ikinci","kisim":2,"madde":23,"sayfa":506},{"metin":"İşlerinde Eshâbın ile meşveret et, onlara danış!","sure":"İmrân","ayet_no":"yüzellidokuzuncu","kisim":2,"madde":23,"sayfa":506},{"metin":"Mekke şehri alınmadan önce, din düşmanları ile harb edenler ve mallarını, Allah yolunda harc edenler ile, Mekke alındıkdan sonra, bunları yapanlar, müsâvî, eşit değildir. Birinciler elbette dahâ yüksekdir. Allahü teâlâ, hepsine Hüsnâyı, ya’nî Cenneti söz verdi","sure":"Hadîd","ayet_no":"onuncu","kisim":2,"madde":23,"sayfa":507},{"metin":"Ağaç altında, sana söz veren mü’minlerden, Allahü teâlâ elbette râzıdır","sure":"Feth","ayet_no":"onsekizinci","kisim":2,"madde":23,"sayfa":507},{"metin":"Yâ Rabbî! Yeryüzünde, fesâd çıkaracak ve kan dökecek olan kulları mı yaratacaksın? Biz, seni tesbîh ediyoruz, hamd ediyoruz. Seni her dürlü aybdan, kusûrdan takdîs ediyoruz dedi","sure":"Bekara","ayet_no":"otuzuncu","kisim":2,"madde":23,"sayfa":507},{"metin":"Onlar, birbirine, her zemân ve çok iyilik edicidir","sure":"Feth","ayet_no":"son","kisim":2,"madde":23,"sayfa":509},{"metin":"Isyân edenler ile harb edip, bunları itâ’ate getirin!","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":512},{"metin":"Mekke-i mükerremenin fethinden önce malını veren ve cihâd eden kimseye, fethden sonra malını dağıtan ve cihâd edenden dahâ büyük derece vardır. Allahü teâlâ, hepsine Cenneti va’d etdi","sure":"Hadîd","ayet_no":"onuncu","kisim":2,"madde":25,"sayfa":516},{"metin":"Ey Peygamberim “sallallahü aleyhi ve sellem”! Sana yardımcı olarak Allahü teâlâ ve mü’minlerden sana tâbi’ olanlar yetişir","sure":"Enfâl","ayet_no":"altmışdördüncü","kisim":2,"madde":25,"sayfa":516},{"metin":"Size gelen belâlar, kabâhatlerinizin cezâsıdır","sure":null,"ayet_no":null,"kisim":2,"madde":25,"sayfa":517},{"metin":"Âdeme önce söyledik. Fekat unutdu. Azm ile, karâr ile yapmadı","sure":null,"ayet_no":null,"kisim":2,"madde":25,"sayfa":519},{"metin":"Allahü teâlâ, onlara zulm etmez. Onlar, kendi kendilerine zulm edip, ağır cezâları hak etdiler","sure":null,"ayet_no":null,"kisim":2,"madde":25,"sayfa":519},{"metin":"Kâfirler: Bu nasıl Peygamberdir? “sallallahü aleyhi ve sellem”. Bizim gibi yiyip içiyor, sokaklarda geziyor. Peygamber olsaydı, kendisine melek gelirdi. Yardımcıları olur, bize onlar da haber verir, Cehennem ile korkuturlardı. Yâhud, Rabbi, para hazîneleri gönderir, yâhud, meyve bağçeleri, çiftlikleri olur, istediğini yirdi dediler...","sure":null,"ayet_no":null,"kisim":2,"madde":25,"sayfa":520},{"metin":"Allahü teâlâ kullarını, selâmet, se’âdet yeri olan Cennetine da’vet ediyor. Dilediğini bu yola kavuşdurur","sure":null,"ayet_no":null,"kisim":2,"madde":28,"sayfa":530},{"metin":"Nefslerine uyanlardan, doğru yolu arayanları, se’âdete ulaşdıran yollara kavuşdururuz","sure":null,"ayet_no":null,"kisim":2,"madde":28,"sayfa":530},{"metin":"Kullarıma hikmet ile ve güzel va’z ile beni tanıt!","sure":"Nahl","ayet_no":null,"kisim":2,"madde":30,"sayfa":537},{"metin":"Ey cin ve ey insan! Gücünüz yeterse, yer yüzünden ve semâlardan dışarı çıkınız. Çıkmanız için, çok kuvvet ister. O kuvvet de sizde yokdur","sure":"Rahmân","ayet_no":null,"kisim":2,"madde":31,"sayfa":553},{"metin":"Erkekler, kadınlar üzerine hâkimdirler. Çünki, Allahü teâlâ, ba’zı kullarını ba’zısından üstün yaratmışdır. Hem de, erkekler, kendi mallarını, onlar için harc ederler. Kadınların iyileri, Allahü teâlâya itâ’at eder ve zevclerinin haklarını gözetirler. Zevcleri hâzır olmadıkları zemân, onların nâmûslarını ve mallarını, Allahın yardımı ile korurlar. Hıyânet etmesinden korkduğunuz kadınlara, zevc haklarını öğretin ve tatlı sözlerle nasîhat edin! Onları yatağınızdan ayırın. Yine uslanmaz iseler, hafîf döğün! Uslanırlarsa, onları üzecek şey yapmayın!","sure":"Nisâ","ayet_no":"otuzüçüncü","kisim":2,"madde":39,"sayfa":600},{"metin":"Müslimân kadınlar, zînetlerini göstermesinler! İş yaparken zarûrî açılanlar günâh olmaz. Baş örtülerini yakalarına kadar örtsünler [Böylece, saçları, kulakları ve göğüsleri iyi örtülsün]","sure":"Nûr","ayet_no":null,"kisim":2,"madde":39,"sayfa":603},{"metin":"Allahı çok zikr eden erkeklerin ve kadınların günâhları afv olur ve çok sevâb verilir","sure":"Ahzâb","ayet_no":"otuzbeşinci","kisim":2,"madde":40,"sayfa":617},{"metin":"Yüz mü’min, ikiyüz kâfire gâlip gelir","sure":"Enfâl","ayet_no":"altmışaltıncı","kisim":2,"madde":42,"sayfa":628},{"metin":"Allahü teâlânın kulları için, yerden çıkardığı zînetleri harâm edecek kimdir?","sure":null,"ayet_no":null,"kisim":2,"madde":43,"sayfa":634},{"metin":"Yerlerde olan herşeyi sizin için yaratdım","sure":"Bekara","ayet_no":null,"kisim":2,"madde":43,"sayfa":636},{"metin":"Belki siz, isrâf eden kavmsiniz!","sure":"Nisâ","ayet_no":null,"kisim":2,"madde":44,"sayfa":640},{"metin":"İsrâf etmeyiniz! Allahü teâlâ, isrâf edenleri sevmez","sure":null,"ayet_no":null,"kisim":2,"madde":44,"sayfa":640},{"metin":"Tebzîr etme! Tebzîr edenler, şeytânların kardeşleridir","sure":"İsrâ","ayet_no":null,"kisim":2,"madde":44,"sayfa":640},{"metin":"Mallarınızı sefîhlere, alçaklara vermeyiniz!","sure":"Nisâ","ayet_no":null,"kisim":2,"madde":44,"sayfa":640},{"metin":"O, isrâf edenlerden idi","sure":"Nisâ","ayet_no":null,"kisim":2,"madde":44,"sayfa":640},{"metin":"Fâiz yiyenler, kıyâmet günü mezârlarından, sar’a hastası gibi perişân kalkacaklardır","sure":"Bekara","ayet_no":"ikiyüzyetmişbeşinci","kisim":2,"madde":44,"sayfa":641},{"metin":"Allahü teâlâ, fâiz alan ve verenlerin mallarının hepsini yok eder. İzini, eserini de bırakmaz. Zekât verenlerin malını elbette artdırır","sure":"Bekara","ayet_no":"ikiyüzyetmişbeşinci","kisim":2,"madde":44,"sayfa":641},{"metin":"Şükr ederseniz, verdiğim ni’metleri elbette artdırırım","sure":"İbrâhîm","ayet_no":"yedinci","kisim":2,"madde":44,"sayfa":642},{"metin":"Ekini hasâd etdiğiniz zemân, fakîrlerin haklarını verin ve isrâf etmeyin. Allahü teâlâ, isrâf edenleri elbette sevmez","sure":null,"ayet_no":null,"kisim":2,"madde":44,"sayfa":644},{"metin":"Ey Habîbim! Malını, kendine kalmıyacak şeklde dağıtma!","sure":"İsrâ","ayet_no":"yirmidokuzuncu","kisim":2,"madde":44,"sayfa":644},{"metin":"Mallarınızı sefîhlere vermeyiniz!","sure":null,"ayet_no":null,"kisim":2,"madde":44,"sayfa":645},{"metin":"Onların hâlinde rüşd görürseniz, mallarını kendilerine teslîm ediniz!","sure":null,"ayet_no":null,"kisim":2,"madde":44,"sayfa":645},{"metin":"Tevekkül îmânın şartıdır","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"Sözünün eri olan İbrâhîm","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"Bir kimse, herşeyden ümmîd kesip, yalnız bana güvenirse, yerde ve göklerde bulunanların hepsi, ona zarar yapmağa, aldatmağa uğraşsalar, onu elbette kurtarırım","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"İlm-i yakîn ile bilseydiniz, Cehennemi elbette görürdünüz","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":681},{"metin":"Hepinizin dünyâya getirilmesi ve âhıretde tekrâr diriltilmesi, bir kişinin yaratılması ve diriltilmesi gibidir","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":682},{"metin":"Onların âhıretdeki hâlleri, dünyâdaki hâlleri gibidir","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":682},{"metin":"Allahü teâlâ bize yetişir. O, çok iyi vekîldir","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":683},{"metin":"Herşeye kuvvet veren, ancak Allahü teâlâdır","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":684},{"metin":"Şeytân, muhtâc hâle düşeceğinizi, size söz veriyor","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":687},{"metin":"Yer yüzündeki her cânlının rızkını, Allahü teâlâ, elbette gönderir","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":687},{"metin":"Allahü teâlânın rızk vermediği, yer yüzünde bir mahlûk yokdur","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":688},{"metin":"Kâfirlerin ve münâfıkların zararlarına, işkencelerine karşılıkda bulunma! Ben onların cezâsını veririm. Onlardan korunmak, kurtulmak için Allahü teâlâya tevekkül et!","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":690},{"metin":"Yapdıkları işkencelere sabr ederiz. Tevekkül ediciler, yalnız Allahü teâlâya tevekkül etmelidir","sure":null,"ayet_no":null,"kisim":2,"madde":47,"sayfa":690},{"metin":"Allahü teâlâ, dilediğini siler. Dilediğini değişdirmez. Ümmül-kitâb, Ondadır","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":698},{"metin":"Ecel, bir ân gecikmez ve vaktinden önce gelmez","sure":null,"ayet_no":null,"kisim":2,"madde":48,"sayfa":699},{"metin":"Herkesin ömrü ve ömürlerin kısalması hep yazılıdır","sure":"Fâtır","ayet_no":null,"kisim":2,"madde":48,"sayfa":699},{"metin":"Siz, ancak Allahü teâlânın dilediğini arzû edersiniz!","sure":null,"ayet_no":null,"kisim":2,"madde":49,"sayfa":701},{"metin":"İnsanları ve cinnîleri ancak, Beni bilip, itâ’at, ibâdet etmeleri için yaratdım!","sure":null,"ayet_no":null,"kisim":2,"madde":49,"sayfa":703},{"metin":"Allahü teâlânın indinde din, islâm dînidir","sure":null,"ayet_no":null,"kisim":2,"madde":49,"sayfa":704},{"metin":"onların kalblerini mühürledik","sure":"Bekara","ayet_no":"yedinci","kisim":2,"madde":49,"sayfa":708},{"metin":"Onların îmân etmiyeceklerini ezelde söyledik","sure":null,"ayet_no":null,"kisim":2,"madde":50,"sayfa":714},{"metin":"Allahü teâlâ, onların kalblerini mühürlemişdir!","sure":null,"ayet_no":null,"kisim":2,"madde":50,"sayfa":714},{"metin":"Ba’zı şeyleri sever, fâideli dersiniz. Hâlbuki o şeyler size zararlıdır","sure":"Bekara","ayet_no":"ikiyüzonaltıncı","kisim":2,"madde":52,"sayfa":722},{"metin":"Onun yaratdıkları pek çokdur. O, herşeyi bilir","sure":null,"ayet_no":null,"kisim":2,"madde":52,"sayfa":723},{"metin":"Beğendiğiniz, sevdiğiniz çok şey vardır ki, sizin için zararlıdır!","sure":"Bekara","ayet_no":"ikiyüzonaltıncı","kisim":2,"madde":52,"sayfa":727},{"metin":"İnsanları ve Cinnîleri ancak, beni bilip itâ’at, ibâdet etmeleri için yaratdım","sure":"Zâriyât","ayet_no":"ellialtıncı","kisim":2,"madde":53,"sayfa":736},{"metin":"Ey Rabbimiz, bizimle kavmimiz arasında sen hak olanı hükm et. Sen hükm edenlerin hayrlısısın!","sure":null,"ayet_no":null,"kisim":2,"madde":55,"sayfa":745},{"metin":"Ey Peygamberim! Allahü teâlâ ve senin yolunda olan mü’minler, sana kâfîdirler!","sure":"Enfâl","ayet_no":"altmışdördüncü","kisim":2,"madde":57,"sayfa":746},{"metin":"İnsan, ihtiyâcsız olunca, elbette azar!","sure":"Enfâl","ayet_no":"altmışdördüncü","kisim":2,"madde":57,"sayfa":746},{"metin":"Onlar iyi bir iş yapdıklarını sanıyor. Biliniz ki, çok yalancıdırlar. Şeytân onları aldatmış, yoldan çıkarmışdır. Allahü teâlâyı o kadar unutdurmuş ki, ne dillerine, ne de gönüllerine getirmezler. Şeytânın askeri, uşakları olmuşlardır. Biliniz ki, şeytânın gürûhü olan bunlar, bitmez tükenmez ni’metleri elden kaçırdı. Sonsuz azâblara yakalandı","sure":null,"ayet_no":null,"kisim":2,"madde":61,"sayfa":749},{"metin":"Kullarım senden beni soruyorlar. Ben onlara çok yakınım!","sure":"Bekara","ayet_no":"yüzseksenaltıncı","kisim":2,"madde":62,"sayfa":753},{"metin":"Üç adam gizli konuşunca, Allah onların dördüncüsü olur. Beş kişi gizli konuşunca, Allah onların altıncısı olur. Dahâ az veyâ dahâ çok kimseler olunca da, her nerede olursa olsunlar, Allah onlarla berâberdir","sure":"Mücâdele","ayet_no":"yedinci","kisim":2,"madde":62,"sayfa":753},{"metin":"Her fırkada bulunanlar, kendi anladıklarını doğru sanırlar","sure":null,"ayet_no":null,"kisim":2,"madde":62,"sayfa":753},{"metin":"Onu gözler anlıyamaz. O ise, gözleri bilir, anlar. O, ihsân sâhibi bilicidir","sure":null,"ayet_no":null,"kisim":2,"madde":67,"sayfa":756},{"metin":"Peygamber göndermedikce azâb yapmayız!","sure":"İsrâ","ayet_no":"onbeşinci","kisim":2,"madde":67,"sayfa":760},{"metin":"Biz, Peygamber göndermedikçe, azâb yapıcı değiliz","sure":"İsrâ","ayet_no":"onbeşinci","kisim":2,"madde":67,"sayfa":762},{"metin":"İlmleri Ona varamaz!","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":766},{"metin":"Allahü teâlâ îmânlarınızı zâyı’ eylemez!","sure":null,"ayet_no":null,"kisim":2,"madde":72,"sayfa":769},{"metin":"Onların çoğu Allahü teâlâya îmân ediyoruz derler. Fekat îmânsızdırlar. Başka şeylere ibâdet ederek müşrik olmuşlardır","sure":null,"ayet_no":null,"kisim":2,"madde":72,"sayfa":769},{"metin":"Onlara, kâfirlere inanmayınız dediğim hâlde, onlar kâfirlerin sözleri ile hareket ediyorlar. Şeytân onları aldatıyor","sure":null,"ayet_no":null,"kisim":3,"madde":2,"sayfa":778},{"metin":"Biz, Allahü teâlânın varlığına, birliğine, herşeyi yaratan O olduğuna inandık, müslimân olduk diyenlerin çoğu, başkalarına ibâdet ve itâ’at ederek ve dahâ birçok hareketleri ve sözleri ile, müşrik oluyorlar","sure":null,"ayet_no":null,"kisim":3,"madde":2,"sayfa":778},{"metin":"Kadına ve erkeğe yüz sopa vurunuz!","sure":null,"ayet_no":null,"kisim":3,"madde":2,"sayfa":780},{"metin":"Mü’minlere söyle, yabancı kadınlara bakmasınlar ve zinâ etmesinler! Ve mü’min kadınlara söyle! Onlar da, yabancı erkeklere bakmasınlar ve zinâ etmesinler!","sure":"Nûr","ayet_no":null,"kisim":3,"madde":2,"sayfa":781},{"metin":"Mü’minlere saldıran zâlimlerle cihâd yapmağa izn verildi","sure":"Hac","ayet_no":"otuzdokuzuncu","kisim":3,"madde":15,"sayfa":842},{"metin":"Verirken noksân, alırken fazla ölçenlere acı azâblar yapacağım","sure":"Mutaffifîn","ayet_no":"birinci","kisim":3,"madde":15,"sayfa":842},{"metin":"İhsân edenlere, elbette rahmetim çok yakındır","sure":null,"ayet_no":null,"kisim":3,"madde":16,"sayfa":845},{"metin":"Mallarınız ve çocuklarınız, Allahü teâlâyı, hâtırlamanıza mâni’ olmasın!","sure":null,"ayet_no":null,"kisim":3,"madde":17,"sayfa":848},{"metin":"Allahü teâlâ, dilediğini seçerek kendine kavuşdurur","sure":"Şûrâ","ayet_no":null,"kisim":3,"madde":27,"sayfa":903},{"metin":"Biliniz ki kalbler, ancak Allahı zikr etmekle itmînâna kavuşur","sure":null,"ayet_no":null,"kisim":3,"madde":27,"sayfa":904},{"metin":"Nereye dönerseniz, orada Allahü teâlâyı bulursunuz!","sure":"Bekara","ayet_no":"yüzonbeşinci","kisim":3,"madde":27,"sayfa":905},{"metin":"Allahü teâlâ, müşriki afv etmiyecekdir","sure":"Nisâ","ayet_no":"kırksekiz ve yüzonaltıncı","kisim":3,"madde":28,"sayfa":907},{"metin":"Allahü teâlânın, günâhlarını iyiliklerle değişdireceği kimseler, onlardır. Allahü teâlânın magfireti, merhameti sonsuzdur","sure":"Furkân","ayet_no":"yetmişinci","kisim":3,"madde":29,"sayfa":910},{"metin":"Bizim gibi bir insan mı bize yol gösterecek, diyerek kâfir oldular","sure":null,"ayet_no":null,"kisim":3,"madde":30,"sayfa":912},{"metin":"Bu nasıl Peygamberdir? Bizim gibi yiyor ve sokaklarda dolaşıyor dediler","sure":"Furkân","ayet_no":null,"kisim":3,"madde":30,"sayfa":912},{"metin":"Yer küresini iki günde yaratdı","sure":null,"ayet_no":null,"kisim":1,"madde":48,"sayfa":915},{"metin":"Allahü teâlâ, gökleri ve yeri altı günde yaratdı ve Arşı, su üzerinde idi","sure":"Hûd","ayet_no":null,"kisim":3,"madde":33,"sayfa":915},{"metin":"Onun Kürsîsi, göklerden ve yerden genişdir","sure":"Bekara","ayet_no":"ikiyüzellibeşinci","kisim":3,"madde":33,"sayfa":915},{"metin":"Kalbleri Allahü teâlâyı zikr etmiyenlere azâb vardır","sure":"Zümer","ayet_no":null,"kisim":3,"madde":37,"sayfa":921},{"metin":"Rabbinizi, yalvararak ve gizli ve sessiz çağırınız","sure":"Zümer","ayet_no":null,"kisim":3,"madde":37,"sayfa":921},{"metin":"Biliniz ki, kalbler, yalnız Allahü teâlâyı zikr etmekle râhat bulur","sure":"Zümer","ayet_no":null,"kisim":3,"madde":37,"sayfa":921},{"metin":"Rabbini, içinden zikr et!","sure":"Zümer","ayet_no":null,"kisim":3,"madde":37,"sayfa":921},{"metin":"Şeytânın askeri elbette mağlûb olacak, ziyân edecekdir","sure":"Mücâdele","ayet_no":"ondokuzuncu","kisim":3,"madde":43,"sayfa":931},{"metin":"Kendinizde bulunmakdadır, niçin görmüyorsunuz?","sure":null,"ayet_no":null,"kisim":3,"madde":44,"sayfa":937},{"metin":"Allahü teâlâ, dilediğini kendine seçer, kendine kavuşmak isteyenlere de, kavuşduran yolu gösterir","sure":null,"ayet_no":null,"kisim":3,"madde":51,"sayfa":953},{"metin":"Belki anlamadıkları için inanmıyorlar. Onun sözünün özünü anlamadılar. Bunlardan önce olanlar da, böyle inanmamışlardı","sure":null,"ayet_no":null,"kisim":3,"madde":51,"sayfa":957},{"metin":"Düâ ediniz! Düânızı kabûl ederim!","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":1036},{"metin":"Temiz olanları severim!","sure":null,"ayet_no":null,"kisim":3,"madde":70,"sayfa":1046},{"metin":"Onlara söyle! Eğer Allahı seviyorsanız, bana tâbi’ olunuz! Allah, bana tâbi’ olanları sever","sure":"İmrân","ayet_no":"otuzbirinci","kisim":3,"madde":70,"sayfa":1051},{"metin":"Ey mü’minler! Dâimâ, her zemân, sâdıklar ile birlikde bulunun!","sure":"Tevbe","ayet_no":"yüzyirminci","kisim":3,"madde":70,"sayfa":1051},{"metin":"Mü’minlere saldıran zâlimlerle cihâd etmeğe izn verildi","sure":null,"ayet_no":null,"kisim":null,"madde":null,"sayfa":1170}],"hadisler":[{"metin":"Ümmetim arasında fitne, fesâd yayıldığı zemân, sünnetime yapışana, yüz şehîd sevâbı vardır.","kaynak":null,"kisim":null,"madde":null,"sayfa":2},{"metin":"Kur’ân-ı kerîme saygı göstermek, E’ûzü okuyarak başlamakla olur ve Kur’ân-ı kerîmin anahtarı, Besmeledir","kaynak":null,"kisim":null,"madde":null,"sayfa":3},{"metin":"Hoca çocuğa, Besmele okur, çocuk da söyleyince, Allahü teâlâ, çocuğun ve anasının ve babasının ve hocasının Cehenneme girmemesi için sened yazdırır","kaynak":null,"kisim":null,"madde":null,"sayfa":3},{"metin":"Hikmet [ya’nî fen ve san’at], mü’minin gayb etdiği malıdır. Nerede bulursa alsın!","kaynak":null,"kisim":null,"madde":null,"sayfa":7},{"metin":"Günâhlardan sakınmayan müslimânların ibâdetleri sahîh olsa da kabûl olmaz","kaynak":"Hadîka","kisim":1,"madde":1,"sayfa":19},{"metin":"Allahü teâlâ, sizin sûretlerinize, mallarınıza, bakmaz. Kalblerinize ve amellerinize bakar","kaynak":null,"kisim":1,"madde":1,"sayfa":20},{"metin":"Bir sâat ilm öğrenmek veyâ öğretmek, sabâha kadar ibâdet etmekden dahâ sevâbdır","kaynak":"Dürr-ül-muhtâr","kisim":1,"madde":1,"sayfa":20},{"metin":"Kur’ân-ı kerîmden kendi aklı ile, kendi düşüncesi ve bilgisi ile ma’nâ çıkaran kâfirdir","kaynak":null,"kisim":1,"madde":8,"sayfa":23},{"metin":"Oğullarınıza yüzmek ve ok atmak öğretiniz! Kadınların, evinde iplik iğirmesi ne güzel eğlencedir","kaynak":null,"kisim":1,"madde":11,"sayfa":25},{"metin":"Hepiniz bir sürünün çobanı gibisiniz. Çoban sürüsünü koruduğu gibi, siz de evlerinizde ve emrleriniz altında olanları Cehennemden korumalısınız! Onlara müslimânlığı öğretmelisiniz! Öğretmez iseniz mes’ûl olacaksınız","kaynak":null,"kisim":1,"madde":18,"sayfa":34},{"metin":"Çok müslimân evlâdı, babaları yüzünden Veyl ismindeki Cehenneme gideceklerdir. Çünki, bunların babaları, yalnız para kazanmak ve keyf sürmek hırsına düşüp ve yalnız dünyâ işleri arkasında koşup, evlâdlarına müslimânlığı ve Kur’ân-ı kerîmi öğretmediler. Ben böyle babalardan uzağım. Onlar da, benden uzakdır. Çocuklarına dinlerini öğretmiyenler, Cehenneme gideceklerdir","kaynak":null,"kisim":1,"madde":18,"sayfa":34},{"metin":"Çocuklarına Kur’ân-ı kerîm öğretenlere veyâ Kur’ân-ı kerîm hocasına gönderenlere, öğretilen Kur’ânın her harfi için, on kerre Kâ’be-i mu’azzama ziyâreti sevâbı verilir ve kıyâmet günü, başına devlet tâcı konur. Bütün insanlar görüp imrenir","kaynak":null,"kisim":1,"madde":18,"sayfa":34},{"metin":"Çocuklarınıza nemâz kılmasını öğretiniz. Yedi yaşına gelince, nemâzı emr ediniz. On yaşına gelince kılmazlar ise, döverek kıldırınız","kaynak":null,"kisim":1,"madde":18,"sayfa":34},{"metin":"Bir müslimânın evlâdı ibâdet edince, kazandığı sevâb kadar, babasına da verilir. Bir kimse, çocuğuna fısk, günâh öğretirse, bu çocuk ne kadar günâh işlerse, babasına da o kadar günâh yazılır","kaynak":null,"kisim":1,"madde":18,"sayfa":34},{"metin":"Zevcesinin ve çocuklarının haklarını îfâ etmiyenin nemâzları, orucları kabûl olmaz","kaynak":"Mürşid-ün-nisâ","kisim":1,"madde":18,"sayfa":34},{"metin":"Birbirinize müslimânlığı öğretiniz. Emr-i ma’rûfu bırakır iseniz, Allahü teâlâ, en kötünüzü başınıza musallat eder ve düâlarınızı kabûl etmez","kaynak":null,"kisim":1,"madde":18,"sayfa":35},{"metin":"Bütün ibâdetlere verilen sevâb, Allah yolunda gazâya verilen sevâba göre, deniz yanında bir damla su gibidir. Gazânın sevâbı da, emr-i ma’rûf ve nehy-i anilmünker sevâbı yanında, denize nazaran bir damla su gibidir","kaynak":null,"kisim":1,"madde":18,"sayfa":35},{"metin":"Îmânın temeli ve en kuvvetli alâmeti, müslimânları sevmek ve müslimânlara düşmanlık edenleri sevmemekdir","kaynak":null,"kisim":1,"madde":19,"sayfa":38},{"metin":"Ümmetimden büyük günâhları olanlara şefâ’at edeceğim","kaynak":null,"kisim":1,"madde":31,"sayfa":58},{"metin":"Allahü teâlâdan istedim ki, benden sonra Alî “radıyallahü anh” halîfe olsun. Melekler dedi ki: Yâ Muhammed “sallallahü aleyhi ve sellem”! Allahü teâlânın dilediği olur. Senden sonra halîfe, Ebû Bekr-i Sıddîkdır.","kaynak":null,"kisim":1,"madde":31,"sayfa":60},{"metin":"Benden sonra halîfe Ebû Bekr olacakdır. Ondan sonra Ömer, ondan sonra Osmân, ondan sonra da sen “radıyallahü anhüm” olacaksın!","kaynak":null,"kisim":1,"madde":31,"sayfa":60},{"metin":"Eshâbıma dil uzatmakdan sakınınız!","kaynak":null,"kisim":1,"madde":31,"sayfa":60},{"metin":"İsmini duyduğunuz kimselerden, yeryüzüne [ya’nî, o zemân bilinen memleketlerin çoğuna] dört kişi mâlik oldu. İkisi mü’min, ikisi de kâfir idi. Mü’min olan iki kişi, Zülkarneyn ile Süleymân “aleyhimesselâm” idi. Kâfir olan ikisi de, Nemrûd ile Buhtunnasar idi. Beşinci olarak, yeryüzüne, benim evlâdımdan biri, ya’nî Mehdî de, mâlik olacakdır","kaynak":null,"kisim":1,"madde":31,"sayfa":62},{"metin":"Kıyâmet kopmadan önce, Allahü teâlâ, benim evlâdımdan birini yaratır ki, ismi benim ismim gibi, babasının ismi, benim babamın ismi gibi olur ve dünyâyı adâletle doldurur. Ondan önce dünyâ zulmle dolu iken, onun zemânında adl ile dolar","kaynak":null,"kisim":1,"madde":31,"sayfa":63},{"metin":"Eshâb-ı Kehf, hazret-i Mehdînin yardımcıları olacakdır ve Îsâ “aleyhisselâm” bunun zemânında gökden inecekdir. Îsâ “aleyhisselâm”, Deccâl ile harb ederken, hazret-i Mehdî, onunla berâber olacakdır. Bunun hükümdârlığı zemânında, her zemânkinin aksine olarak ve hesâbların tersine olarak, Ramezân-ı şerîfin ondördüncü günü güneş tutulacakdır ve birinci gecesinde ay tutulacakdır","kaynak":null,"kisim":1,"madde":31,"sayfa":63},{"metin":"Benî İsrâîl, yetmişbir fırkaya ayrılmışdı. Bunlardan yetmişi Cehenneme gidip, ancak bir fırkası kurtulmuşdur. Nasârâ da, yetmişiki fırkaya ayrılmışdı. Yetmişbiri Cehenneme gitmişdir. Bir zemân sonra, benim ümmetim de yetmişüç kısma ayrılır. Bunlardan yetmişikisi, Cehenneme gidip, yalnız bir fırkası kurtulur","kaynak":null,"kisim":1,"madde":31,"sayfa":63},{"metin":"Bir zerrecik [ya’nî çok az] bir günâhdan kaçınmak, bütün cin ve insanların ibâdetleri toplamından dahâ iyidir","kaynak":null,"kisim":1,"madde":31,"sayfa":64},{"metin":"Gizli yapılan günâhın tevbesini gizli yapınız! Âşikâre yapılan günâhın tevbesini âşikâre yapınız! Günâhınızı bilenlere, tevbenizi duyurunuz!","kaynak":null,"kisim":1,"madde":31,"sayfa":65},{"metin":"Benden sonra müslimânlar arasında çok ayrılık olacakdır. O zemânlarda yaşıyanlar benim yoluma ve Hulefâ-i râşidînin “aleyhimürrıdvân” yoluna yapışsın! Sonradan meydâna çıkan, moda olan şeylerden kaçınsın! Çünki, dinde yenilik, reform yapmak doğru yoldan çıkmakdır. Benden sonra, dinde yapılacak değişikliklerin hepsi dinsizlikdir","kaynak":null,"kisim":1,"madde":31,"sayfa":66},{"metin":"Senin müezzinin mizmârdır","kaynak":null,"kisim":null,"madde":null,"sayfa":70},{"metin":"Önce gelenleriniz, sonra gelenleriniz; küçüğünüz, büyüğünüz; dirileriniz, ölüleriniz; insanlarınız, cinleriniz; en müttekî, itâ’atli kulum gibi olsanız, büyüklüğüm artmaz. Aksine olarak, hepiniz, bana karşı duran, Peygamberlerimi “aleyhimüsselâm” aşağı gören, düşmanım gibi olsanız, ülûhiyyetimden bir şey eksilmez. Allahü teâlâ, sizden ganîdir, Ona hiçbiriniz lâzım değildir. Siz ise, var olmanız için ve varlıkda kalabilmeniz için ve her şeyinizle, hep Ona muhtâcsınız","kaynak":null,"kisim":1,"madde":36,"sayfa":74},{"metin":"İnsan ölünce, kıyâmeti kopmuş olur","kaynak":null,"kisim":null,"madde":null,"sayfa":89},{"metin":"Îmânında veyâ ibâdetinde bid’at, bozukluk bulunan bir kimseye, Allah için sert bakanın kalbini, Allahü teâlâ îmânla doldurur ve korkudan korur","kaynak":null,"kisim":1,"madde":41,"sayfa":90},{"metin":"Günâh işleyeni, eliniz ile men’ ediniz, buna kuvvetiniz yetmezse, söz ile mâni’ olunuz. Bunu da yapamaz iseniz, kalbiniz ile beğenmeyiniz! Bu ise, îmânın en aşağısıdır","kaynak":null,"kisim":1,"madde":41,"sayfa":94},{"metin":"Allahü teâlâ, Cebrâîl aleyhisselâma, filân şehri yerin dibine geçir, diye emr etdi. Cebrâîl, yâ Rabbî! Bu şehrdeki filânca kulun sana bir ân ısyân etmedi. Hep itâ’at ve ibâdet ediyor deyince, onu da berâber geçir! Zîrâ günâh işleyenleri görünce, bir kerrecik yüzünü değişdirmedi","kaynak":null,"kisim":1,"madde":41,"sayfa":94},{"metin":"Dîninizin direği, temeli vera’dır","kaynak":null,"kisim":1,"madde":42,"sayfa":96},{"metin":"Hiçbir şey vera’ gibi olamaz","kaynak":null,"kisim":1,"madde":42,"sayfa":96},{"metin":"Bir nemâzı özrsüz, vaktinden sonra kılan, seksen hukbe Cehennemde yanacakdır. Bir hukbe seksen senedir. Her senesi üçyüzaltmış gündür. Her günü, seksen dünyâ senesidir","kaynak":"Tergîb-üs-salât","kisim":1,"madde":43,"sayfa":98},{"metin":"Bir kimse, bir günâh işler, sonra pişmân olursa, bu pişmânlığı, günâhına keffâret olur. Ya’nî, afvına sebeb olur","kaynak":null,"kisim":1,"madde":43,"sayfa":98},{"metin":"Günâhı olan kimse, istigfâr eder ve tevbe eder, sonra bu günâhı tekrâr yapar, sonra yine istigfâr söyler, tevbe eder. Üçüncüye yine yapar ve yine tevbe ederse, dördüncü olarak yapınca, büyük günâh yazılır","kaynak":null,"kisim":1,"madde":43,"sayfa":98},{"metin":"Müsevvifler helâk oldu","kaynak":null,"kisim":1,"madde":43,"sayfa":98},{"metin":"Allahü teâlâ buyuruyor ki: Ey kulum! Emr etdiğim farzları yap, insanların en âbidi olursun. Yasak etdiğim harâmlardan sakın, vera’ sâhibi olursun. Verdiğim rızka kanâ’at eyle, insanların en ganîsi olursun, kimseye muhtâc kalmazsın","kaynak":null,"kisim":1,"madde":43,"sayfa":99},{"metin":"Vera’ sâhibi ol ki, insanların en âbidi olursun!","kaynak":null,"kisim":1,"madde":43,"sayfa":99},{"metin":"Bana malını, cânını, Ebû Bekr kadar çok fedâ eden, başkası yokdur. Eğer, dost edinseydim, elbette Ebû Bekri dost edinirdim","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"Allahü teâlâ, beni size Peygamber gönderdi. İnanmadınız. Ebû Bekr inandı. Bana malı ile, cânı ile yardım etdi. Onu hiç incitmeyin ve Ona hurmet ve ta’zîm edin!","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"Benden sonra Peygamber gelmiyecekdir. Eğer gelseydi, elbette Ömer Peygamber olurdu","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"Onları seven, beni sevdiği için sever","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"Onlara düşmanlık eden, bana düşman olduğu için eder","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"İslâmın binâsı beş direk üzerine kurulmuşdur. Birincisi, Eşhedü en lâ ilâhe illallah ve eşhedü enne Muhammeden abdühu ve resûlüh, demek ve bunun ma’nâsına inanmakdır","kaynak":null,"kisim":1,"madde":46,"sayfa":109},{"metin":"Kıyâmetde, sahîfesinde çok istigfâr bulunanlara, müjdeler olsun!","kaynak":null,"kisim":1,"madde":46,"sayfa":110},{"metin":"Farz nemâzlarından sonra Âyet-el-kürsî okuyan kimse ile Cennet arasında, ölümden başka mâni’ yokdur","kaynak":null,"kisim":1,"madde":46,"sayfa":111},{"metin":"Bu düâyı gündüz okuyan, o günün şükrünü yapmış olur. Gece okuyunca, o gecenin şükrünü îfâ etmiş olur","kaynak":null,"kisim":1,"madde":46,"sayfa":111},{"metin":"Oruc, mü’mini Cehennemden koruyan bir kalkandır","kaynak":null,"kisim":1,"madde":46,"sayfa":111},{"metin":"Kabûl olan bir hac, geçmiş günâhları yok eder","kaynak":null,"kisim":1,"madde":46,"sayfa":111},{"metin":"Âlimlerin uykusu ibâdetdir","kaynak":null,"kisim":1,"madde":46,"sayfa":113},{"metin":"Bir Velî kuluma düşmanlık eden, benimle harb etmiş olur. Kulumu bana yaklaşdıran şeyler arasında, en sevdiğim, ona farz etdiğim şeydir. Nâfile ibâdet [de] yaparak, bana yaklaşan kulumu çok severim. Çok sevdiğim kulumun işiten kulağı, gören gözü, tutan eli, yürüyen ayağı olurum. İstediğini elbette veririm. Bana sığındığı zemân, elbette korurum","kaynak":null,"kisim":1,"madde":46,"sayfa":113},{"metin":"Herşeyin menba’ı vardır. İhlâsın, takvânın menba’ı, kaynağı, Âriflerin kalbleridir","kaynak":"Künûz-üd-dekâık","kisim":1,"madde":46,"sayfa":114},{"metin":"Ey Eshâbım! Siz öyle bir zemânda geldiniz ki, Allahü teâlânın emrlerinden onda dokuzunu yapıp, birini yapmazsanız, helâk olursunuz, Cehenneme gidersiniz! Bir zemân gelecek ki, o zemânın mü’minleri, emrlerin birini yapabilip, dokuzunu bıraksalar, Cehennemden kurtulurlar. O zemânda îmânı olanlara müjdeler olsun!","kaynak":null,"kisim":1,"madde":48,"sayfa":116},{"metin":"Her yüz senede bir müceddid zâhir olur. Ümmetimin işlerini yeniler","kaynak":null,"kisim":1,"madde":50,"sayfa":120},{"metin":"Gusl abdesti almağa kalkan bir kimseye, üzerindeki kıl adedince [ya’nî pekçok demekdir] sevâb verilir. O kadar günâhı afv olur. Cennetdeki derecesi yükselir. Guslü için ona verilecek sevâb, dünyâda bulunan herşeyden dahâ hayrlı olur. Allahü teâlâ, Meleklere, bu kuluma bakınız! Gece, üşenmeden kalkıp, benim emrimi düşünerek, cenâbetden gusl ediyor. Şâhid olunuz ki, bu kulumun günâhlarını afv ve magfiret eyledim buyurur","kaynak":"Dürr-ül-muhtâr","kisim":1,"madde":54,"sayfa":132},{"metin":"Kirlenince, çabuk gusl abdesti alın! Çünki kirâmen kâtibîn melekleri, cünüb gezen kimseden incinir","kaynak":null,"kisim":1,"madde":54,"sayfa":132},{"metin":"Resim, köpek ve cünüb kimse bulunan eve rahmet melekleri girmez","kaynak":null,"kisim":1,"madde":54,"sayfa":132},{"metin":"Misvâk kullanarak kılınan nemâz, misvâksız nemâzdan yetmiş kat üstündür","kaynak":null,"kisim":1,"madde":54,"sayfa":142},{"metin":"Komşu kadına ve arkadaşların kadınlarına şehvet ile bakmak, yabancı kadınlara bakmakdan on kat dahâ günâhdır. Evli kadınlara bakmak, kızlara bakmakdan bin kat dahâ çok günâhdır. Zinâ günâhları da böyledir","kaynak":null,"kisim":1,"madde":58,"sayfa":164},{"metin":"Allah için yapılan cihâdda düşmanı gözleyen veyâ Allah korkusundan ağlıyan veyâ harâmlara bakmıyan gözler, kıyâmetde Cehennem ateşini görmiyeceklerdir","kaynak":null,"kisim":1,"madde":58,"sayfa":164},{"metin":"Ananın ayağını öpmek, Cennet kapısının eşiğini öpmek gibidir","kaynak":null,"kisim":1,"madde":58,"sayfa":166},{"metin":"Cebrâîl aleyhisselâm Kâ’be kapısı yanında iki gün bana imâm oldu. İkimiz, fecr doğarken sabâh nemâzını, güneş tepeden ayrılırken öğleyi, herşeyin gölgesi kendi boyu uzayınca ikindiyi, güneş batarken [üst kenârı gaybolunca] akşamı ve şafak kararınca yatsıyı kıldık. İkinci günü de, sabâh nemâzını, hava aydınlanınca; öğleyi, herşeyin gölgesi kendi boyunun iki katı uzayınca; ikindiyi, bundan hemen sonra, akşamı, oruc bozulduğu zemân, yatsıyı gecenin üçde biri olunca kıldık. Sonra, yâ Muhammed, senin ve geçmiş Peygamberlerin nemâz vaktleri budur. Ümmetin, beş vakt nemâzın herbirini, bu kıldığımız iki vaktin arasında kılsınlar dedi","kaynak":null,"kisim":1,"madde":60,"sayfa":175},{"metin":"Nemâz vaktlerinin bir evveli vardır. Bir de sonu vardır","kaynak":"Tergîb-üs-salât","kisim":1,"madde":60,"sayfa":175},{"metin":"İbâdetlerin en kıymetlisi, evvel vaktinde kılınan nemâzdır","kaynak":"Künûz-üd-dekâık","kisim":1,"madde":60,"sayfa":194},{"metin":"Bir zemân gelecek, âmirler, imâmlar, nemâzı öldürecekler, vaktinden sonraya bırakacaklardır. Sen, nemâzını vaktinde kıl! Senden sonra, cemâ’at olurlarsa, onlarla da, tekrâr kıl! İkinci kıldığın nâfile olur","kaynak":"Müslim","kisim":1,"madde":60,"sayfa":194},{"metin":"İblîs yer yüzüne indirilince, Allahü teâlâya sordu: Âdem aleyhisselâm indirilince, kullarına Cennet, se’âdet yolunu göstermek için, ona kitâb ve Peygamberler verdin. Ona vereceğin kitâb ve Peygamberler nelerdir? Allahü teâlâ: Melekler ve meşhûr Peygamberler ve dört meşhûr kitâbdır, buyurdu. Kullarını azdırmak için, bana hangi kitâbları ve Peygamberleri vereceksin, dedi. Senin kitâbın, nefsi azdıran şi’rler ve mûsikîdir. Peygamberlerin, kâhinler, falcılar, büyücülerdir ve aklı gideren, kalbleri karartan gıdaların da, Besmelesiz yinilen, içilen şeyler ve serhoş eden içkilerdir. Nasîhatların, yalan, evin, spor sahaları ve hamamlar ve tuzakların, çıplak gezen kızlar, mescidlerin, fısk meclisleridir. Müezzinlerin, mizmârlar [çalgılar]dır, buyurdu.","kaynak":null,"kisim":1,"madde":61,"sayfa":208},{"metin":"Mü’min ile kâfiri ayıran fark, nemâzdır","kaynak":null,"kisim":1,"madde":63,"sayfa":210},{"metin":"Allahü teâlâ, hergün beş vakt nemâz kılmağı farz etdi. Kıymet vererek ve şartlarına uyarak, hergün beş vakt nemâz kılanı Cennete sokacağını, Allahü teâlâ söz verdi","kaynak":null,"kisim":1,"madde":63,"sayfa":212},{"metin":"Nemâz kılmıyanın, islâmdan nasîbi yokdur!","kaynak":null,"kisim":1,"madde":63,"sayfa":212},{"metin":"İnsan ile küfr arasındaki fark, nemâzı terk etmekdir!","kaynak":"Künûz-üd-dekâık","kisim":1,"madde":63,"sayfa":212},{"metin":"Nemâzı özrsüz kılmıyan kimseye, Allahü teâlâ onbeş sıkıntı verir. Bunlardan altısı dünyâda, üçü ölüm zemânında, üçü kabrde, üçü kabrden kalkarkendir. Dünyâda olan altı azâb: 1 — Nemâz kılmıyanın ömründe bereket olmaz. 2 — Allahü teâlânın sevdiği kimselerin güzelliği, sevimliliği kendinde kalmaz. 3 — Hiçbir iyiliğine sevâb verilmez. [Bu hadîs-i şerîf gösteriyor ki, farzları vaktinde kılmıyanların sünnetleri kabûl olmaz. Ya’nî sünnetlerine sevâb verilmez.] 4 — Düâları kabûl olmaz. 5 — Onu kimse sevmez. 6 — Müslimânların iyi düâlarının buna fâidesi olmaz. Ölürken çekeceği azâblar: 1 — Zelîl, kötü, çirkin can verir. 2 — Aç olarak ölür. 3 — Çok su içse de, susuzluk acısı ile ölür. Kabrde çekeceği acılar: 1 — Kabr onu sıkar. Kemikleri birbirine geçer. 2 — Kabri ateşle doldurulur. Gece, gündüz onu yakar. 3 — Allahü teâlâ, kabrine çok büyük yılan gönderir. Dünyâ yılanlarına benzemez. Hergün, her nemâz vaktinde onu sokar. Bir ân bırakmaz. Kıyâmetde çekeceği azâblar: 1 — Cehenneme sürükliyen azâb melekleri yanından ayrılmaz. 2 — Allahü teâlâ, onu kızgın olarak karşılar. 3 — Hesâbı çok çetin olup, Cehenneme atılır","kaynak":null,"kisim":1,"madde":63,"sayfa":213},{"metin":"Her nemâzdan sonra, üç kerre, Estagfirullahel’azîm ellezî lâ ilâhe illâ huv el-hayyel-kayyûme ve etûbü ileyh okuyanın, bütün günâhları afv olur","kaynak":null,"kisim":1,"madde":64,"sayfa":218},{"metin":"Beş vakt farz nemâzdan sonra yapılan düâ kabûl olur","kaynak":null,"kisim":1,"madde":64,"sayfa":218},{"metin":"Unutulmuş bir sünnetimi meydâna çıkarana yüz şehîd sevâbı vardır","kaynak":null,"kisim":1,"madde":64,"sayfa":219},{"metin":"Gece seher vaktinde ve nemâzlardan sonra yapılan düâ kabûl olunur","kaynak":"Dürr-ül-muhtâr","kisim":1,"madde":64,"sayfa":219},{"metin":"Yehûdîlere benzememek için nemâzları, na’lın ile kılınız","kaynak":null,"kisim":1,"madde":68,"sayfa":237},{"metin":"Elinize geçen resmleri yırtınız, bozunuz!","kaynak":null,"kisim":1,"madde":68,"sayfa":238},{"metin":"Davulu ve mizmârı yok etmek için emr olundum","kaynak":null,"kisim":1,"madde":69,"sayfa":247},{"metin":"Müttekî bir âlim ile nemâz kılan, bir Peygamber ile kılmış gibidir","kaynak":null,"kisim":1,"madde":70,"sayfa":248},{"metin":"Bir zemân gelecek maymun sıfatlı, insan sûretli kimseler, minbere çıkıp, sizlere, din aleyhindeki sözleri, dinsizliği, din diye söyliyeceklerdir","kaynak":null,"kisim":1,"madde":71,"sayfa":259},{"metin":"Cum’a günü tırnağını kesen kimse, bir hafta, belâlardan emîn olur","kaynak":null,"kisim":1,"madde":71,"sayfa":262},{"metin":"İnsanın parmakla gösterilmesi, kendisine kötülük olarak yetişir","kaynak":null,"kisim":1,"madde":71,"sayfa":263},{"metin":"Bıyıklarınızı kısaltınız! Sakalınızı uzatınız!","kaynak":"Berîka","kisim":1,"madde":71,"sayfa":264},{"metin":"Bir müslimân, Cum’a günü gusl abdesti alıp, Cum’a nemâzına giderse, bir haftalık günâhları afv olur ve her adımı için sevâb verilir","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Günlerin en kıymetlisi Cum’adır. Cum’a günü, bayram günlerinden ve aşûre gününden dahâ kıymetlidir. Cum’a, dünyâda ve Cennetde mü’minlerin bayramıdır","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Cum’a nemâzı kılmıyanların kalblerini, Allahü teâlâ mühürler. Gâfil olurlar","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Bir kimse, mâni’ yok iken, üç Cum’a nemâzı kılmazsa, Allahü teâlâ, kalbini mühürler. Ya’nî, iyilik yapmaz olur","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Cum’a günlerinde bir ân vardır ki, mü’minin o ânda etdiği düâ red olmaz","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"Cum’a günü sabâh nemâzından önce, üç kerre Estagfirullahel’azîm ellezî lâ ilâhe illâ hüvel hayyelkayyûme ve etûbü ileyh okuyanın, kendinin ve anasının ve babasının bütün günâhları afv olur","kaynak":"Tergîb-üs-salât","kisim":1,"madde":71,"sayfa":265},{"metin":"Cum’a nemâzından sonra, yedi def’a İhlâs ve Mu’avvizeteyn okuyanı, Allahü teâlâ, bir hafta, kazâdan, belâdan ve kötü işlerden korur","kaynak":"Tergîb-üs-salât","kisim":1,"madde":71,"sayfa":265},{"metin":"Cumartesi günleri yehûdîlere, pazar günleri nasârâya verildiği gibi, Cum’a günü, müslimânlara verildi. Bugün, müslimânlara hayr, bereket, iyilik vardır","kaynak":null,"kisim":1,"madde":71,"sayfa":265},{"metin":"İnsânlar, kendilerine iyilik edenleri sever","kaynak":null,"kisim":null,"madde":null,"sayfa":267},{"metin":"Bir nemâzı uykuda geçiren veyâ unutan kimse, sonraki nemâzı cemâ’at ile kılarken hâtırlarsa, imâmla nemâzı bitirip, sonra önceki nemâzını kazâ etsin! Bundan sonra, imâmla kıldığını tekrâr kılsın!","kaynak":null,"kisim":1,"madde":74,"sayfa":272},{"metin":"Allahü teâlânın en çok sevdiği amel, hubb-i fillah ve buğd-ı fillahdır","kaynak":null,"kisim":1,"madde":74,"sayfa":276},{"metin":"Üzerinde farz nemâzı borcu olan kimse, kazâsını kılmadan nâfile kılarsa, boş yere zahmet çekmiş olur. Bu kimse, kazâsını ödemedikçe, Allahü teâlâ, onun nâfile nemâzlarını kabûl etmez","kaynak":null,"kisim":1,"madde":74,"sayfa":278},{"metin":"Bu haber, farz borcu olanların, sünnetlerinin ve nâfilelerinin kabûl olmıyacağını göstermekdedir. Sünnetlerin, farzları temâmlıyacağını biliyoruz. Bunun ma’nâsı, farzlar yapılırken, bunların kemâllerine sebeb olan birşey kaçırılırsa, sünnetler, kılınan farzın kemâl bulmasına sebeb olur. Farz borcu olanın kabûl edilmiyen sünnetleri bir işe yaramaz","kaynak":null,"kisim":1,"madde":74,"sayfa":278},{"metin":"Temâm yapılmamış olan nemâz, zekât ve başka farzlar, nâfileler ile temâmlanacakdır","kaynak":null,"kisim":1,"madde":74,"sayfa":278},{"metin":"Bir kimse, nemâzını temâmlamadı ise, o nemâzın üzerine, temâmlanıncaya kadar, nâfile nemâzları eklenir","kaynak":null,"kisim":1,"madde":74,"sayfa":279},{"metin":"Bir kimse, kendisine farz yapdığım ibâdeti yapmakla bana yaklaşdığı gibi, hiçbirşeyle yaklaşamaz","kaynak":null,"kisim":1,"madde":74,"sayfa":279},{"metin":"Kıyâmetde, önce nemâzdan sorulacakdır. Nemâz doğru kılındı ise, kurtulacakdır. Nemâzı bozuk ise, işi kötü olacakdır. Farz nemâzında birşey noksan olursa, nâfileleri ile temâmlanacakdır","kaynak":null,"kisim":1,"madde":74,"sayfa":279},{"metin":"Emrlerimi gücünüz yetdiği kadar yapınız. Yasak etdiklerimden sakınınız!","kaynak":null,"kisim":1,"madde":74,"sayfa":282},{"metin":"Yasak edilmiş şeyin zerresini yapmamak, bütün insanların ve cinnin ibâdetlerinden dahâ çok sevâbdır","kaynak":null,"kisim":1,"madde":74,"sayfa":282},{"metin":"Bir insanın mâ-lâ-ya’nî ile vakt geçirmesi, Allahü teâlânın, onu sevmediğinin alâmetidir","kaynak":null,"kisim":1,"madde":74,"sayfa":282},{"metin":"İki farz nemâzı bir araya getirmek, büyük günâhlardandır","kaynak":"Tergîb-üs-salât","kisim":1,"madde":74,"sayfa":283},{"metin":"Bir nemâzı, vakti çıkdıkdan sonra kılan kimseyi, Allahü teâlâ, seksen hukbe Cehennemde bırakacakdır","kaynak":"Tergîb-üs-salât","kisim":1,"madde":74,"sayfa":283},{"metin":"Nemâz dînin direğidir. Nemâz kılan, dînini doğrultmuş olur. Nemâz kılmıyan, dînini yıkmış olur","kaynak":null,"kisim":1,"madde":74,"sayfa":283},{"metin":"Kıyâmet günü, îmândan sonra, ilk süâl nemâzdan olacakdır","kaynak":null,"kisim":1,"madde":74,"sayfa":283},{"metin":"Bir nemâzı, bilerek, özrsüz kılmıyan kimse, seksen hukbe Cehennemde kalacakdır!","kaynak":null,"kisim":1,"madde":74,"sayfa":283},{"metin":"Büyük günâh işleyenlere şefâ’at edeceğim","kaynak":null,"kisim":1,"madde":74,"sayfa":286},{"metin":"Unutulmuş bir sünnetimi meydâna çıkarana, yüz şehîd sevâbı verilecekdir","kaynak":null,"kisim":1,"madde":77,"sayfa":290},{"metin":"Müslimânların kabri Cennet bağçelerindendir","kaynak":null,"kisim":1,"madde":77,"sayfa":290},{"metin":"Bir yere gelen kimse E’ûzü bikelimâtillâhit-tâmmâti min şerri mâ haleka okursa, o yerden kalkıncaya kadar, ona hiçbirşey zarar, kötülük yapmaz","kaynak":null,"kisim":1,"madde":77,"sayfa":291},{"metin":"İlm öğrenmekde olanın kırk yıllık nafakası olsa da, buna zekât vermek câizdir","kaynak":"Dürr-ül-muhtâr","kisim":1,"madde":78,"sayfa":307},{"metin":"Malınızın zekâtını veriniz! Biliniz ki, zekâtını vermiyenlerin, nemâzı, orucu, haccı ve cihâdı ve îmânı yokdur","kaynak":null,"kisim":1,"madde":78,"sayfa":311},{"metin":"Allahü teâlâ, iyilik edenlere, karşılığını elbette verecekdir","kaynak":null,"kisim":1,"madde":78,"sayfa":311},{"metin":"Zekât vererek, malınızı zarardan koruyunuz!","kaynak":null,"kisim":1,"madde":78,"sayfa":311},{"metin":"Ey Âdem oğlu! Benim malım, benim malım dersin. O maldan senin olan, yiyerek yok etdiğin, giyerek eskitdiğin ve Allah için vererek, sonsuz yaşatdığındır","kaynak":null,"kisim":1,"madde":78,"sayfa":312},{"metin":"Ramezân ayı gelince, Cennet kapıları açılır. Cehennem kapıları kapanır ve şeytânlar bağlanır","kaynak":"Buhârî","kisim":1,"madde":79,"sayfa":313},{"metin":"Ey Müslimânlar! Üzerinize öyle büyük bir ay gölge vermek üzeredir ki, bu aydaki bir gece [Kadr gecesi], bin aydan dahâ fâidelidir. Allahü teâlâ, bu ayda, hergün oruc tutulmasını emr etdi. Bu ayda, geceleri terâvîh nemâzı kılmak da sünnetdir. Bu ayda, Allah için ufak bir iyilik yapmak, başka aylarda, farz yapmış gibidir. Bu ayda, bir farz yapmak, başka ayda yetmiş farz yapmak gibidir. Bu ay, sabr ayıdır. Sabr edenin gideceği yer Cennetdir. Bu ay, iyi geçinmek ayıdır. Bu ayda mü’minlerin rızkı artar. Bir kimse, bu ayda, bir orucluya iftâr verirse, günâhları afv olur. Hak teâlâ, onu Cehennem ateşinden âzâd eder. O oruclunun sevâbı kadar, ona sevâb verilir","kaynak":"Buhârî","kisim":1,"madde":79,"sayfa":313},{"metin":"Bir kimse, Ramezân ayında oruc tutmağı farz bilir, vazîfe bilir ve orucun sevâbını, Allahü teâlâdan beklerse, geçmiş günâhları afv olur","kaynak":null,"kisim":1,"madde":79,"sayfa":313},{"metin":"Allahü teâlâ benim ümmetime, Ramezân-ı şerîfde beş şey ihsân eder ki, bunları hiçbir Peygambere vermemişdir: 1 — Ramezânın birinci gecesi, Allahü teâlâ mü’minlere rahmet eder. Rahmet ile bakdığı kuluna hiç azâb etmez. 2 — İftâr zemânında, oruclunun ağzı kokusu, Allahü teâlâya, her kokudan dahâ güzel gelir. 3 — Melekler, Ramezânın her gece ve gündüzünde, oruc tutanların afv olması için düâ eder. 4 — Allahü teâlâ, oruc tutanlara, âhıretde vermek için, Ramezân-ı şerîfde Cennetde yer ta’yîn eder. 5 — Ramezân-ı şerîfin son günü, oruc tutan mü’minlerin hepsini afv eder","kaynak":null,"kisim":1,"madde":79,"sayfa":313},{"metin":"Ayı görünce oruc tutunuz! Tekrâr görünce, orucu bırakınız!","kaynak":null,"kisim":1,"madde":79,"sayfa":314},{"metin":"Hasîslerin en kötüsü, [kesmesi vâcib olduğu hâlde] kurban kesmiyendir","kaynak":null,"kisim":1,"madde":81,"sayfa":325},{"metin":"Kurban kesecek kimse, Zilhicce ayı girince, saçını kesmesin ve tırnak kesmesin!","kaynak":null,"kisim":1,"madde":81,"sayfa":326},{"metin":"Tüccârın, pazarcıların çoğu fâcirdir!","kaynak":null,"kisim":1,"madde":83,"sayfa":337},{"metin":"Yalan yere yemîn ederek, birinin malını alan kimse, kıyâmet günü, Allahü teâlâyı gadablı görecekdir","kaynak":null,"kisim":1,"madde":83,"sayfa":337},{"metin":"Îmân sâhibi, her kabâhati yapabilir. Fekat, hiyânet yapamaz ve yalan söyliyemez","kaynak":null,"kisim":1,"madde":83,"sayfa":337},{"metin":"Yalan üç yerde câiz olur: Harbde [ve her zemân, din düşmanlarının zararından korunmak veyâ müslimânları korumak için]. İkincisi, iki müslimânı barışdırmak için, birinden diğerine iyi lâf getirmek. Üçüncüsü, zevcelerini idâre etmek için","kaynak":null,"kisim":1,"madde":83,"sayfa":337},{"metin":"Yalan yemîn ederek bir müslimânın hakkını alan kimsenin gideceği yer, Cehennemdir","kaynak":null,"kisim":1,"madde":83,"sayfa":338},{"metin":"Babam hakkı için diyerek yemîn etmeyiniz! Yemîn, Allah ismi ile olur","kaynak":null,"kisim":1,"madde":83,"sayfa":338},{"metin":"Emânet, ya’nî nâmus için yemîn eden, bizden değildir","kaynak":null,"kisim":1,"madde":83,"sayfa":338},{"metin":"Kadın, yanında bir mahremi olmadan hacca gidemez!","kaynak":"Künûz-üd-dekâık","kisim":1,"madde":84,"sayfa":340},{"metin":"Beni ziyâret için gelip, başka bir iş yapmıyarak, yalnız ziyâret edene kıyâmetde şefâ’at etmek, bende hakkı olur","kaynak":null,"kisim":1,"madde":84,"sayfa":349},{"metin":"Mescidimi Yemendeki San’â şehrine kadar genişletseler, hepsi mescidim olur","kaynak":null,"kisim":1,"madde":84,"sayfa":350},{"metin":"Farz nemâzı kılmamış olanın nâfile nemâzları kılması, vakti temâm olmuş hâmile kadına benzer. Çocuğu olacağı günlerde, çocuğu düşürür, aldırır. Çocuğu yok olduğu için, bu kadına, hâmile denemez. Ana da denemez. Bu kimse de böyledir. Farz nemâzlarını ödemedikce, Allahü teâlâ, nâfile nemâzlarını kabûl etmez","kaynak":null,"kisim":1,"madde":85,"sayfa":357},{"metin":"Tanıdığınız ve tanımadığınız müslimânlara selâm veriniz!","kaynak":null,"kisim":1,"madde":90,"sayfa":364},{"metin":"Birbirinize selâm veriniz! Birbirinize yiyecek ikrâm ediniz! Akrabânızın haklarını gözetiniz! Gece, herkes uyurken nemâz kılınız! Bunları yaparak, selâmetle Cennete giriniz!","kaynak":null,"kisim":1,"madde":90,"sayfa":364},{"metin":"Karşılaşdığınız zemân, birbirinize eğilmeyiniz, kucaklaşmayınız!","kaynak":"Berîka","kisim":1,"madde":90,"sayfa":365},{"metin":"Müslimânın müslimân üzerinde beş hakkı vardır: Selâmına cevâb vermek, hastasını yoklamak, cenâzesinde bulunmak, da’vetine gitmek ve aksırıp elhamdülillah diyene, yerhamükellah diyerek cevâb vermek","kaynak":null,"kisim":1,"madde":90,"sayfa":365},{"metin":"Başkalarına benzeyenler bizden değildir. Yehûdîlere ve hıristiyanlara benzemeyiniz! Yehûdîler parmakları ile işâret ederek, hıristiyanlar elleri ile işâret ederek, mecûsîler de eğilerek selâm verir","kaynak":null,"kisim":1,"madde":90,"sayfa":365},{"metin":"Hangimiz zâlim isek, yalancı isek, Allahü teâlâ ona la’net etsin, diyelim!","kaynak":null,"kisim":1,"madde":92,"sayfa":369},{"metin":"Kalk, yâ Ebâ Ubeyde!","kaynak":null,"kisim":null,"madde":null,"sayfa":370},{"metin":"Yâ Ömer! Kızını, Ebû Bekrden ve Osmândan “radıyallahü anhüm” dahâ iyi birisine versem ister misin?","kaynak":null,"kisim":1,"madde":95,"sayfa":381},{"metin":"Her asrda, her zemânda yaşıyan insanların en iyilerinden, seçilmişlerinden dünyâya getirildim","kaynak":null,"kisim":1,"madde":97,"sayfa":386},{"metin":"Allahü teâlâ, İsmâ’îl “aleyhisselâm” evlâdından, Kinâne ismindeki kimseyi ve onun sülâlesinden, Kureyş ismindeki zâtı beğendi, seçdi. Kureyş evlâdından da, Hâşim oğullarını sevdi. Onlardan da, beni süzüp seçdi","kaynak":null,"kisim":1,"madde":97,"sayfa":386},{"metin":"Allahü teâlâ, insanları yaratdı. Beni insanların en iyi kısmından vücûde getirdi. Sonra, bu kısmlarından en iyisini Arabistânda yetişdirdi. Beni bunlardan vücûde getirdi. Sonra evlerden, âilelerden en iyilerini seçip, beni bunlardan meydâna getirdi. O hâlde, benim rûhum ve cesedim, mahlûkların en iyisidir. Benim silsilem, ecdâdım en iyi insanlardır","kaynak":null,"kisim":1,"madde":97,"sayfa":386},{"metin":"Benim dedelerimin hiçbiri zinâ yapmadı. Allahü teâlâ, beni, tayyîb, iyi babalardan, temiz analardan getirdi. Dedelerimden birinin iki oğlu olsaydı, ben bunların en hayrlısında, en iyisinde bulunurdum","kaynak":null,"kisim":1,"madde":97,"sayfa":387},{"metin":"Ölüleri kötüliyerek, dirileri incitmeyiniz","kaynak":null,"kisim":1,"madde":97,"sayfa":388},{"metin":"Allahü teâlâ, Peygamberimize ikrâm ederek, vedâ’ haccında ana babasını diriltdi. Resûlüne îmân etdiler. Bunu, Kurtubînin ve Muhammed bin Ebû Bekr ibni Nâsırüd-dînin bildirdikleri sahîh hadîs beyân buyurmakdadır. Benî-İsrâîlin öldürdüğü kimseyi diriltip kâtilini haber vermesi ve Îsâ aleyhisselâmın ve Muhammed aleyhisselâmın düâları ile nice mevtâları diriltmesi de böyle ikrâm idi. (Cehennemlik olanlar için benden magfiret isteme!) meâlindeki âyetin Resûlullahın mubârek ana ve babası için olduğu sözü doğru değildir. (Müslim)in bildirdiği (Babam ve baban ateşdedirler) hadîs-i şerîfi ictihâd ile söylenmiş idi. Îmânlı oldukları sonradan bildirildi","kaynak":null,"kisim":1,"madde":97,"sayfa":388},{"metin":"Âdem aleyhisselâmdan babam Abdüllaha gelinceye kadar, hep nikâhlı ana babalardan geldim. Hiçbir babamın nikâhsız, ya’nî zinâ ile çocuğu olmadı","kaynak":null,"kisim":1,"madde":97,"sayfa":390},{"metin":"Ben sizin en iyiniz olduğum gibi, babam da, babalarınızdan dahâ iyidir","kaynak":null,"kisim":1,"madde":97,"sayfa":391},{"metin":"Bir kimse nemâz sonunda, üç def’a Sübhâne rabbike âyet-i kerîmesini okursa, yetişir mikdârda sevâba kavuşur","kaynak":null,"kisim":1,"madde":98,"sayfa":392},{"metin":"Kıyâmet günü büyük ölçeklerle, bol sevâb kazanmak istiyen kimse, bir meclisden kalkınca Sübhâne rabbike âyet-i kerîmesini okusun!","kaynak":null,"kisim":1,"madde":98,"sayfa":392},{"metin":"Bir kulum bana yaklaşırsa, ona sesleri duyurur ve saklı şeyleri gösteririm","kaynak":null,"kisim":1,"madde":98,"sayfa":395},{"metin":"Unutulmuş bir sünnetimi meydâna çıkarana yüz şehîd sevâbı vardır!","kaynak":null,"kisim":1,"madde":64,"sayfa":397},{"metin":"İnsanlara müdârâ için gönderildim","kaynak":"Künûz","kisim":2,"madde":1,"sayfa":398},{"metin":"Yeryüzünü küfr kaplamadıkca ve heryerde küfr ve kâfirlik yapılmadıkca, hazret-i Mehdî gelmez","kaynak":null,"kisim":null,"madde":null,"sayfa":398},{"metin":"Kıyâmet yaklaşdıkca, fitneler çoğalır. Gece başlarken karanlığın artması gibi olur. Sabâh evinden mü’min olarak çıkan çok kimse akşam kâfir olarak döner. Akşam mü’min iken, gece safâlarında îmânları gider. Böyle zemânlarda, evinde kapanmak fitneye karışmakdan hayrlıdır. Kenârda kalan, ileri atılandan hayrlıdır. O gün oklarınızı kırınız! Silâhlarınızı, kılınclarınızı bırakınız! Herkesi tatlı dil ile, güler yüzle karşılayınız! Evinizden çıkmayınız!","kaynak":null,"kisim":2,"madde":1,"sayfa":399},{"metin":"Üç dürlü baba vardır: Dünyâya getiren baba, kızını veren baba ve ilm öğreten baba. Bunların hayrlısı, üstâdıdır","kaynak":null,"kisim":2,"madde":3,"sayfa":401},{"metin":"Lâ ilâhe illallah ehline kâfir demeyiniz! Bunlara kâfir diyenin kendisi kâfir olur","kaynak":null,"kisim":2,"madde":4,"sayfa":408},{"metin":"Birinize derd ve belâ gelince, Yûnüs Peygamberin düâsını okusun! Allahü teâlâ Onu muhakkak kurtarır. Düâ şudur: Lâ ilâhe illâ ente sübhâneke innî küntü minez-zâlimîn","kaynak":null,"kisim":2,"madde":11,"sayfa":427},{"metin":"Sabâh, kalkınca, üç kerre Bismillâhillezî lâ-yedurru ma’ asmihî şey’ün fil-erdı velâ fissemâi ve hüves-semî’ul’alîm okuyana akşama kadar, hiç derd, belâ gelmez","kaynak":"Tergîb-üs-salât","kisim":2,"madde":11,"sayfa":427},{"metin":"Her mü’minin kalbinde, Allahü teâlânın bir vâ’ızı vardır","kaynak":null,"kisim":2,"madde":13,"sayfa":428},{"metin":"Kur’ân-ı kerîm okuyan çok kimse vardır ki, Kur’ân-ı kerîm bunlara la’net eder","kaynak":null,"kisim":2,"madde":14,"sayfa":429},{"metin":"Oruc tutan çok kimse vardır ki, onların orucu, yalnız açlık ve susuzluk çekmek olur","kaynak":null,"kisim":2,"madde":14,"sayfa":429},{"metin":"Müslimân demek, müslimânlara eli ile, dili ile zarâr vermiyen kimse demekdir","kaynak":null,"kisim":null,"madde":null,"sayfa":430},{"metin":"Îmânı kâmil olanınız, ahlâkı güzel olanınızdır!","kaynak":null,"kisim":2,"madde":14,"sayfa":430},{"metin":"Kâfirlere karşı malınızla, cânınızla ve dilinizle cihâd ediniz!","kaynak":null,"kisim":2,"madde":16,"sayfa":437},{"metin":"Ok atmasını ve ata binmesini öğreniniz!","kaynak":"Hadîka","kisim":2,"madde":16,"sayfa":438},{"metin":"Ok atmasını öğrenip, sonra unutan bizden değildir","kaynak":"Hadîka","kisim":2,"madde":16,"sayfa":438},{"metin":"Oyunun fâidesi olmaz. Yalnız, ok atmağı öğrenmek ve atını terbiye etmek ve âilesi ile oynamak hakdır","kaynak":"Hadîka","kisim":2,"madde":16,"sayfa":438},{"metin":"Kur’ân-ı kerîmi üç günden önce hatm eden, ma’nâsını anlayamaz","kaynak":null,"kisim":2,"madde":16,"sayfa":440},{"metin":"Ümmetimden, Ebû Hanîfe adında biri gelecekdir. Bu, kıyâmet günü, ümmetimin ışığı olacakdır","kaynak":"Dürr-ül-muhtâr","kisim":2,"madde":16,"sayfa":441},{"metin":"Nu’mân bin Sâbit adında ve Ebû Hanîfe denilen biri gelecek, Allahü teâlânın dînini ve benim sünnetimi canlandıracakdır","kaynak":"Dürr-ül-muhtâr","kisim":2,"madde":16,"sayfa":441},{"metin":"Îmân süreyyâ yıldızına çıksa, Fâris oğullarından biri, elbette alıp getirir","kaynak":"Müslim","kisim":2,"madde":16,"sayfa":442},{"metin":"İnsanların en hayrlısı, benim asrımda bulunan müslimânlardır. Ya’nî Eshâb-ı kirâmdır. Onlardan sonra en iyileri, onlardan sonra gelenlerdir. Ya’nî Tâbi’îndir. Onlardan sonra da en iyileri, onlardan sonra gelenlerdir. Onlardan sonra gelenlerde, yalan yayılır. Bunların sözlerine ve işlerine inanmayınız!","kaynak":"Müslim","kisim":2,"madde":16,"sayfa":442},{"metin":"Kıyâmete yakın ilm azalır, cehâlet artar","kaynak":null,"kisim":2,"madde":16,"sayfa":442},{"metin":"Allahü teâlâ, kulum farzları yapmakla bana yaklaşdığı gibi başka şeyle yaklaşamaz. Kulum nâfile ibâdetleri yapınca, onu çok severim. Öyle olur ki, benimle işitir. Benimle görür. Benimle herşeyi tutar. Benimle yürür. Benden her ne isterse veririm. Bana sığınınca, onu korurum buyurdu","kaynak":"Hadîka","kisim":2,"madde":17,"sayfa":449},{"metin":"Müslimân ismini taşıyanlardan en çok korkduğum kimse, Kur’ân-ı kerîmin ma’nâsını, yerinden değişdirenlerdir","kaynak":"Buhârî","kisim":2,"madde":17,"sayfa":449},{"metin":"Çölde yalnız kalan kimse, birşey gayb ederse, ey Allahın kulları, bana yardım ediniz desin! Çünki, Allahü teâlânın, sizin göremediğiniz kulları vardır","kaynak":null,"kisim":2,"madde":17,"sayfa":452},{"metin":"Öldükden sonra da, hayâtda olduğum gibi bilirim","kaynak":"Künûz","kisim":2,"madde":17,"sayfa":452},{"metin":"Arabistânın şark tarafından bir kimseler çıkar. Kur’ân-ı kerîmi okurlar. Fekat, Kur’ân-ı kerîm, bunların buğazlarından aşağıya gitmez. Ok yaydan çıkar gibi islâmiyyetden çıkarlar. Yüzleri de hep traşlıdır","kaynak":null,"kisim":2,"madde":17,"sayfa":454},{"metin":"Korkulu olan yerde, üç kerre: Ey Allahın kulları! Bana yardım ediniz demeli","kaynak":null,"kisim":2,"madde":17,"sayfa":457},{"metin":"Birşeyden zarâr gören, abdest alıp iki rek’at nemâz kılsın! Sonra; Yâ Rabbî! Senden istiyorum. Senin âlemlere rahmet olan Peygamberin Muhammed aleyhisselâmı vesîle kılarak sana yalvarıyorum. Yâ Muhammed! Dileğimi kabûl etmesi için Rabbime seni vesîle ediyorum. Yâ Rabbî! Onu bana şefâ’atcı et desin","kaynak":null,"kisim":null,"madde":null,"sayfa":457},{"metin":"Âlimler, Peygamberlerin vârisleridir","kaynak":null,"kisim":2,"madde":17,"sayfa":467},{"metin":"Ümmetim yetmişüç fırkaya ayrılacak, bunlardan yalnız biri Cennete gidecekdir. Bunlar, benim ve Eshâbımın yolunda olanlardır","kaynak":null,"kisim":2,"madde":17,"sayfa":467},{"metin":"Ümmetimin ayrılması rahmetdir","kaynak":null,"kisim":2,"madde":17,"sayfa":467},{"metin":"Kitâbullahda ve benim sünnetimde bulamadıklarınızı, Eshâbımın sözlerinden alınız! Eshâbım, gökdeki yıldızlar gibidir. Hangisine uyarsanız, hidâyete kavuşursunuz. Eshâbımın birbirlerinden ayrılıkları rahmetdir","kaynak":null,"kisim":2,"madde":17,"sayfa":467},{"metin":"Her asr, önceki asrdan dahâ bozuk olur. Böylece kıyâmete kadar hep bozulur","kaynak":null,"kisim":2,"madde":17,"sayfa":469},{"metin":"Bid’at sâhibine hurmet eden kimse, islâmiyyeti yıkmağa yardım etmiş olur","kaynak":null,"kisim":2,"madde":17,"sayfa":472},{"metin":"Fitne veyâ bid’at yayıldığı ve Eshâbım kötülendiği zemânda, hakkı bilen, bilgisini müslimânlara duyursun! Hakkı, ya’nî doğru yolu bildiği hâlde, müslimânlara duyurmayanlara, Allahü teâlâ ve melekler ve bütün insanlar la’net eylesin! Allahü teâlâ, bu kimsenin farzlarını ve nâfile ibâdetlerini kabûl etmez","kaynak":null,"kisim":2,"madde":17,"sayfa":472},{"metin":"Ümmetimden, Ehl-i beytimi sevenlere şefâ’at edeceğim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Ümmetimden, büyük günâh işliyenlere şefâ’at edeceğim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Eshâbıma dil uzatanlardan başka, herkese şefâ’at edebilirim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Ümmetimden, nefsine zulm edenlere, nefslerine aldananlara şefâ’at edeceğim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Ümmetimden, günâhları çok olanlara şefâ’at edeceğim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Kıyâmet günü, mezârdan önce çıkan ben olacağım ve en önce şefâ’at eden ben olacağım","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Kıyâmet günü, en önce ben şefâ’at edeceğim","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Şefâ’atime inanmıyan, ona kavuşamaz","kaynak":null,"kisim":2,"madde":18,"sayfa":476},{"metin":"Kabrimi ziyâret eden kimseye şefâ’at etmek bana vâcib oldu","kaynak":"Beyhekî","kisim":2,"madde":18,"sayfa":476},{"metin":"Kabrimi ziyâret edenin şefâ’atcisiyim","kaynak":"Beyhekî","kisim":2,"madde":18,"sayfa":476},{"metin":"Kabristâna giren kimse, Yasîn sûresini okusa, o gün meyyitlerin azâbları hafîfler. Meyyitlerin sayısı kadar, ona da sevâb verilir","kaynak":null,"kisim":2,"madde":18,"sayfa":477},{"metin":"Onbir ihlâs okuyup, sevâbı ölülere gönderilirse, mevtâların sayısınca ona da sevâb verilir","kaynak":null,"kisim":2,"madde":18,"sayfa":477},{"metin":"Defnden sonra cemâ’at dağılırken, ölü, bunların ayak sesini işitir","kaynak":null,"kisim":2,"madde":18,"sayfa":478},{"metin":"Allahü teâlânın, bir kulunu sevmemesinin alâmeti, onun mâ-lâ-ya’nî ile vakt geçirmesidir","kaynak":null,"kisim":2,"madde":19,"sayfa":480},{"metin":"Bir müctehid, âyet-i kerîmeden ve hadîs-i şerîfden [amele âid] bir hükm çıkarırken, isâbet ederse, buna on sevâb verilir. Hatâ ederse, bir sevâb verilir","kaynak":null,"kisim":2,"madde":21,"sayfa":493},{"metin":"İslâmiyyet değirmeni, otuzbeş sene veyâhud otuzyedi sene devâm edecekdir","kaynak":null,"kisim":2,"madde":23,"sayfa":511},{"metin":"Ümmetimden ba’zı kimseler meydâna çıkacak, Eshâbımı kötüliyeceklerdir. Bunlar, müslimânlıkdan ayrılacaklardır","kaynak":null,"kisim":2,"madde":23,"sayfa":511},{"metin":"Bir kimse, şeytâna la’net ederse, ben zâten mel’ûn oldum. Bu la’netin bana zarârı olmaz der. Yâ Rabbî! Beni şeytândan koru derse, eyvâh bel kemiğimi kırdın der","kaynak":null,"kisim":2,"madde":24,"sayfa":513},{"metin":"Şeytâna söğmeyiniz! Şerrinden, Allahü teâlâya sığınınız","kaynak":null,"kisim":2,"madde":24,"sayfa":513},{"metin":"Ümmetimden herhangi biri, Uhud dağı kadar altın sadaka verse, Eshâbımın bir müd arpa sadakasına verilen sevâba kavuşamaz","kaynak":null,"kisim":2,"madde":25,"sayfa":516},{"metin":"Dünyâ kâfirlerin Cennetidir","kaynak":null,"kisim":2,"madde":25,"sayfa":517},{"metin":"İşçiye, alnının teri kurumadan hakkını veriniz","kaynak":null,"kisim":2,"madde":26,"sayfa":527},{"metin":"Nikâh yapmak, benim sünnetimdir. Sünnetimi yapmıyan kimse, benden değildir","kaynak":null,"kisim":2,"madde":34,"sayfa":564},{"metin":"Kadın, yâ malı için veyâ güzelliği için, yâhud dîni için alınır. Siz dîni olanı alınız! Malı için alan, malına kavuşamaz. Yalnız cemâl için alan, cemâlinden mahrûm kalır","kaynak":null,"kisim":2,"madde":34,"sayfa":565},{"metin":"Mehr vermemek niyyeti ile nikâh yapan kimse, kıyâmet günü hırsızlar arasında haşr olunacakdır","kaynak":null,"kisim":2,"madde":34,"sayfa":569},{"metin":"Bunların çocukları za’îf, hastalıklı olur","kaynak":null,"kisim":2,"madde":34,"sayfa":570},{"metin":"Ev satın almadan evvel, komşuların nasıl olduklarını araşdırınız! Yola çıkmadan evvel, yol arkadaşınızı seçiniz!","kaynak":null,"kisim":2,"madde":38,"sayfa":596},{"metin":"Komşuya hurmet etmek, anaya hurmet etmek gibi lâzımdır","kaynak":null,"kisim":2,"madde":38,"sayfa":596},{"metin":"Komşusu, şerrinden emîn olmıyan kimse, Allahü teâlâya îmân etmemişdir","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Zimmî komşunun bir hakkı, müslimân komşunun iki hakkı, akrabâ olan komşunun üç hakkı vardır","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Evinizde pişen yemekden, komşunuzun hakkını veriniz!","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Sıkıntıya düşen komşusuna yardım eden, sıkıntısını gideren kimseye, Allahü teâlâ kıyâmet günü kıymetli elbise giydirecekdir","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Allahü teâlâ, bir sâlih müslimânın hurmetine, komşularından binlerce belâyı, felâketi uzaklaşdırır","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Kendisinin iyi mi, kötü mü olduğunu anlamak istiyen kimse, sâlih, hâlis olan komşularının kendisi hakkında ne dediklerini öğrensin! İyi kimsedir diyorlarsa, ind-i ilâhîde iyi olduğunu anlasın!","kaynak":null,"kisim":2,"madde":38,"sayfa":597},{"metin":"Dört şeyi yapan, ya’nî kocasına hıyânet etmiyen, beş vakt nemâz kılan, Ramezân-ı şerîfde oruc tutan ve [onsekiz erkekden] başkasına, [başı, saçı, kolları, bacakları] açık olarak görünmiyen kadın Cennete gidecekdir","kaynak":null,"kisim":2,"madde":39,"sayfa":598},{"metin":"Beş şeyi yapan kadın Cehennemden kurtulur: Beş vakt nemâzını kılar, Ramezân ayında orucunu tutar, zevcini, anasını babasını üzmez, yüzünü ve saçlarını yabancı erkeklere göstermez, dünyâ sıkıntılarına sabr eder","kaynak":null,"kisim":2,"madde":39,"sayfa":598},{"metin":"Müslimânların en iyisi, en fâidelisi, zevcesine karşı iyi ve fâideli olandır","kaynak":null,"kisim":2,"madde":39,"sayfa":599},{"metin":"Gazâ için sarf edilen, köle âzâd etmek için, fakîre sadaka vermek için ve evindekilerin nafakası için sarf edilen altınların en üstünü ve sevâbı çok olanı, evin nafakasına verilen altının sevâbıdır.","kaynak":null,"kisim":2,"madde":39,"sayfa":600},{"metin":"Bir erkek, zevcesini döğerse, kıyâmetde ben onun da’vâcısı olurum","kaynak":null,"kisim":2,"madde":39,"sayfa":600},{"metin":"Her dürlü lehv harâmdır. Yalnız, zevce ile oynamak, at ve silâh ile ta’lîm, yarış yapmak câizdir","kaynak":null,"kisim":2,"madde":39,"sayfa":602},{"metin":"Kadının neresine olursa olsun, şehvet ile bakan kimsenin gözlerine kıyâmet günü erimiş kurşun dökülecek, sonra Cehenneme atılacakdır","kaynak":"Berîka","kisim":2,"madde":39,"sayfa":603},{"metin":"Yabancı genc kadının elini tutan kimsenin eline kıyâmet günü ateş doldurulacakdır","kaynak":null,"kisim":2,"madde":39,"sayfa":603},{"metin":"İki zevcesi olup da, ikisine müsâvî bakmıyan kimse, kıyâmet günü, mahşer meydânına yarı iğrilmiş olarak gelecekdir","kaynak":null,"kisim":2,"madde":39,"sayfa":605},{"metin":"Bir kimse, kızını fâsıka [kötü kimseye] verirse, Allahü teâlânın emânetine hıyânet etmiş olur. Emânete hıyânet edenlerin gideceği yer, Cehennemdir","kaynak":null,"kisim":2,"madde":39,"sayfa":605},{"metin":"Kızını fâsıka veren kimse, mel’ûndur","kaynak":null,"kisim":2,"madde":39,"sayfa":605},{"metin":"Şefâ’atime kavuşmak istiyen, kızını fâsıka vermesin!","kaynak":null,"kisim":2,"madde":39,"sayfa":605},{"metin":"Yâ Alî! Üç şeyi gecikdirme! Nemâzı evvel vaktinde kıl! Hâzırlanmış cenâzenin nemâzını hemen kıl! Dul veyâ kızı küfvü isteyince, hemen evlendir!","kaynak":null,"kisim":2,"madde":39,"sayfa":605},{"metin":"Halâl kazanmak her müslimâna farzdır","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Çok kimse vardır ki, yidikleri ve giydikleri harâmdır. Sonra ellerini kaldırıp düâ ederler. Böyle düâ, nasıl kabûl olunur?","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Harâm yiyenlerin ne farzları, ne de sünnetleri kabûl olmaz","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"On liralık elbisenin, bir lirası harâm olsa, o elbise ile kılınan nemâzlar kabûl olmaz","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Harâm ile beslenen vücûdün ateşde yanması dahâ iyidir","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Malın halâlden mi, harâmdan mı geldiğini düşünmiyenler, Cehenneme, neresinden atılırsa atılsınlar, Allahü teâlâ, onlara acımıyacakdır","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"İbâdet on kısmdır, dokuz kısmı, halâl kazanmakdır","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Allahü teâlâ buyuruyor ki, harâmdan kaçınanlara hesâb sormağa utanırım","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Bir dirhem fâiz [almak ve vermek], otuz zinâdan dahâ günâhdır","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Harâm maldan verilen sadaka kabûl edilmez. Saklanırsa, Cehenneme gidinceye kadar, ona yolluk olur","kaynak":null,"kisim":2,"madde":40,"sayfa":607},{"metin":"Bir müslimân, tehlükeli olan şeyin korkusundan dolayı, tehlükesiz şeyden sakınmadıkca, müttekî olamaz!","kaynak":null,"kisim":2,"madde":40,"sayfa":608},{"metin":"İnsanların en kötüsü, köşkler, çeşidli yemekler, renkli elbiseler içinde, boş oturup, herkese hoş gelen, lüzûmsuz sözlerle vakt geçirenlerdir","kaynak":null,"kisim":2,"madde":40,"sayfa":610},{"metin":"Her yıl, kendinden önceki yıldan dahâ kötü olacakdır","kaynak":null,"kisim":2,"madde":40,"sayfa":611},{"metin":"İstemeden verilen şeyi alınız! Allahü teâlânın gönderdiği rızkdır","kaynak":null,"kisim":2,"madde":40,"sayfa":613},{"metin":"Allaha ve Âhıret gününe inanan kimse, şerâb içilen sofraya oturmasın!","kaynak":null,"kisim":2,"madde":40,"sayfa":615},{"metin":"Kâr haddi koymayınız! Fiyât koyan, Allahü teâlâdır","kaynak":"Dürr-ül-muhtâr","kisim":2,"madde":40,"sayfa":616},{"metin":"Ey Allahın kulları! Hasta olunca, tedâvî etdiriniz! Çünki Allahü teâlâ, hastalık gönderince, ilâcını da gönderir","kaynak":null,"kisim":2,"madde":41,"sayfa":618},{"metin":"Şerâb, üzüm ve hurmadan olur","kaynak":null,"kisim":2,"madde":42,"sayfa":625},{"metin":"Suyu, alkollü içki içenler gibi içmek harâmdır","kaynak":null,"kisim":2,"madde":42,"sayfa":626},{"metin":"Çok içildiği zemân serhoş eden şeyin, az içilmesi de harâmdır","kaynak":null,"kisim":2,"madde":42,"sayfa":627},{"metin":"Şerâb içmek, büyük günâhların en büyüğüdür. Bütün kötülüklerin anasıdır, başıdır. Şerâb içen, nemâz kılmaz. Anası ile, halası ile, teyzesi ile zinâ eder","kaynak":"Künûz-üd-dekâık","kisim":2,"madde":42,"sayfa":627},{"metin":"Şerâb içen ile arkadaşlık etmeyiniz! Cenâzesine gitmeyiniz! Buna kız vermeyiniz ve onun kızı ile evlenmeyiniz! Muhakkak biliniz ki, şerâb içen, kıyâmet günü, mezârdan yüzü kara, gözleri mâvi olarak kalkar. Dili sarkmış, pis kokulu olur. Herkes, bunun pis kokusundan kaçar","kaynak":"Künûz-üd-dekâık","kisim":2,"madde":42,"sayfa":627},{"metin":"Şerâb içen Cennete girmez","kaynak":null,"kisim":2,"madde":42,"sayfa":627},{"metin":"Şerâb içmeği âdet eden, vesene tapan gibidir","kaynak":null,"kisim":2,"madde":42,"sayfa":628},{"metin":"Bir yudum şerâb içene, Allahü teâlâ üç gün gadab eder","kaynak":null,"kisim":2,"madde":42,"sayfa":628},{"metin":"Şerâbda devâ, ilâc hâssası yokdur. Hastalık yapar","kaynak":null,"kisim":2,"madde":42,"sayfa":628},{"metin":"Gece nemâz kılanların yüzü güzel olur","kaynak":null,"kisim":2,"madde":42,"sayfa":628},{"metin":"Şübheli şeyleri yapan, harâm da işler","kaynak":null,"kisim":2,"madde":43,"sayfa":631},{"metin":"Soğan, sarmısak yiyen, mescidimize gelmesin!","kaynak":null,"kisim":2,"madde":43,"sayfa":631},{"metin":"Söylemediğim birşeyi hadîs diyerek yalan söyliyen, Cehennemde ateşden kazık üzerine oturtulacakdır","kaynak":"Müslim","kisim":2,"madde":43,"sayfa":633},{"metin":"Kıyâmet günü herkes, dört süâle cevâb vermedikce hesâbdan kurtulamıyacakdır: Ömrünü nasıl geçirdi. İlmi ile nasıl amel etdi. Malını nereden, nasıl kazandı ve nerelere harc etdi. Cismini, bedenini nerede yordu, hırpaladı?","kaynak":"Müslim","kisim":2,"madde":44,"sayfa":640},{"metin":"Allahü teâlâ, bir kuluna mal ve ilm verir. Bu kul da harâmlardan kaçınır. Akrabâsını sevindirir. Malından, hakkı olanları bilip verir ise, Cennetin yüksek derecesine gider","kaynak":null,"kisim":2,"madde":44,"sayfa":641},{"metin":"İyiliklerin başı açlıkdır. Kötülüklerin başı toklukdur","kaynak":null,"kisim":2,"madde":45,"sayfa":648},{"metin":"Sağ el ile yiyiniz. Sağ el ile içiniz","kaynak":null,"kisim":2,"madde":45,"sayfa":648},{"metin":"İnsan kalbi, tarladaki ekin gibidir. Yemek, yağmur gibidir. Fazla su, ekini kurutduğu gibi, fazla gıdâ kalbi öldürür","kaynak":null,"kisim":2,"madde":45,"sayfa":649},{"metin":"Çok yiyeni, çok içeni Allahü teâlâ sevmez","kaynak":null,"kisim":2,"madde":45,"sayfa":649},{"metin":"Günâhı çok olan, çok su dağıtsın!","kaynak":null,"kisim":2,"madde":45,"sayfa":650},{"metin":"Allahü teâlâ, kuluna derd vermek isterse, sakalını yolmağı ve tırnağını ısırmağı âdet eder","kaynak":null,"kisim":2,"madde":45,"sayfa":650},{"metin":"Üç şey, bedeni besler: Güzel koku, yumuşak kumaşdan güzel elbise ve bal yimek","kaynak":null,"kisim":2,"madde":45,"sayfa":651},{"metin":"Ümmetim hulbenin fâidesini bilse, ağırlığı kadar altın verip, satın alırdı","kaynak":null,"kisim":2,"madde":46,"sayfa":673},{"metin":"Ümmetimden bir kısmını, bana gösterdiler. Dağları, sahrâları doldurmuşlardı. Böyle çok olduklarına şaşdım ve sevindim. Sevindin mi, dediler, evet dedim. Bunlardan ancak yetmişbin adedi hesâbsız Cennete girer dediler. Bunlar hangileridir diye sordum. İşlerine sihr, büyü, dağlamak, fal karışdırmayıp, Allahü teâlâdan başkasına, tevekkül ve i’timâd etmiyenlerdir buyuruldu","kaynak":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"Allahü teâlâya tam tevekkül etseydiniz, kuşların rızkını verdiği gibi, size de gönderirdi. Kuşlar, sabâh mi’deleri boş, aç gider. Akşam mi’deleri dolmuş, doymuş olarak döner","kaynak":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"Bir kimse, Allahü teâlâya sığınırsa, Allahü teâlâ, onun her işine yetişir. Hiç ummadığı yerden, ona rızk verir. Her kim, dünyâya güvenirse, onu dünyâda bırakır","kaynak":null,"kisim":2,"madde":47,"sayfa":677},{"metin":"Gadab, ya’nî asabiyyet, Cehennem ateşinden bir parçadır","kaynak":null,"kisim":2,"madde":47,"sayfa":681},{"metin":"Bir kimse geceyi, yarın yapacağı işleri düşünmekle geçirir. Hâlbuki o iş, bu kimsenin felâketine sebeb olacakdır. Allahü teâlâ, bu kuluna acıyıp, o işi yapdırmaz. O ise, iş olmadığı için, üzülür. Bu işim neden olmıyor. Kim yapdırmıyor. Bana kim düşmanlık ediyor diye arkadaşlarına kötü gözle bakmağa başlar. Hâlbuki, Allahü teâlâ, ona merhamet ederek felâketden korumuşdur","kaynak":null,"kisim":2,"madde":47,"sayfa":687},{"metin":"Bir kimse, âilesi ile buluşdukda, azl eylemez ise, ya’nî çocuk olmasına mâni’ olmazsa, çocuk olsa da olmasa da, bu kimseye, şehîd oluncıya kadar cihâd eden bir yeğid sevâbı verilir","kaynak":null,"kisim":2,"madde":47,"sayfa":691},{"metin":"İnsan, kendine zulm edene bed düâ eder. Böylece, hakkını, dünyâda almış olur. Belki, zâlimin hakkı da, kendine geçmiş olur","kaynak":null,"kisim":null,"madde":null,"sayfa":692},{"metin":"Bütün Meleklerden işitdim ki, ümmetine söyle, hacâmat yapdırsınlar. Ya’nî kan aldırsınlar dediler","kaynak":null,"kisim":2,"madde":47,"sayfa":693},{"metin":"Arabî ayın onyedinci veyâ ondokuzuncu veyâ yirmibirinci günleri hacâmat olunuz ki, kan artarsa [ya’nî tansiyon yükselirse], ölüme sebeb olur","kaynak":null,"kisim":2,"madde":47,"sayfa":693},{"metin":"Allahü teâlânın ölüme sebeb yapdığı hastalıklardan birisi, kanın artmasıdır","kaynak":null,"kisim":2,"madde":47,"sayfa":693},{"metin":"Mûsâ “aleyhisselâm”, Yâ Rabbî! Hastalığı yapan kimdir, hastalığı iyi eden kimdir, dedi. Cenâb-ı Hak, her ikisini de yapan benim, buyurdu. O hâlde, tabîbe ne lüzûm var deyince, onlar, şifâ için yaratdığım sebebleri bilir ve kullarıma verir. Ben de onlara, bu yoldan rızk ve sevâb veririm, buyurdu","kaynak":null,"kisim":2,"madde":47,"sayfa":694},{"metin":"Şübhe edilen altını, ateşle mu’âyene etdikleri gibi, Allahü teâlâ, insanları derd ile, belâ ile imtihân eder. Ba’zısı, belâ ateşinden hâlis olarak çıkar. Ba’zısı da, bozuk olarak çıkar","kaynak":null,"kisim":2,"madde":47,"sayfa":694},{"metin":"Sıtma hastalığı, insanın günâhlarının hepsini temizler. Dolu dânesinde toz olmadığı gibi, sıtmalının günâhı kalmaz","kaynak":null,"kisim":2,"madde":47,"sayfa":695},{"metin":"Mü’minlerde, üç şeyden biri bulunur: Kıllet ya’nî fakîrlik, ıllet ya’nî hastalık, zillet, ya’nî i’tibârsızlık","kaynak":null,"kisim":2,"madde":47,"sayfa":695},{"metin":"Allahü teâlâ buyurdu ki: Hastalık benim kemendim, tuzağımdır ve fakîrlik zındânımdır. Buralara sevdiklerimi sokarım","kaynak":null,"kisim":2,"madde":47,"sayfa":695},{"metin":"Allahü teâlâ, harâm olan şeylerde, size şifâ yaratmamışdır","kaynak":"Buhârî","kisim":2,"madde":47,"sayfa":695},{"metin":"Allahü teâlâdan âfiyet isteyiniz. Belâ istemeyiniz!","kaynak":null,"kisim":2,"madde":47,"sayfa":696},{"metin":"İnsanların kalbi Rahmânın kudretindedir. Kalbleri, dilediği gibi çevirir","kaynak":null,"kisim":2,"madde":48,"sayfa":698},{"metin":"Kader, tedbîr ile, sakınmakla değişmez. Fekat kabûl olan düâ, o belâ gelirken korur","kaynak":null,"kisim":2,"madde":48,"sayfa":698},{"metin":"Kazâ-i mu’allakı, hiçbirşey değişdiremez. Yalnız düâ değişdirir ve ömrü, yalnız, ihsân, iyilik artdırır","kaynak":null,"kisim":2,"madde":48,"sayfa":698},{"metin":"Bir kimse, bütün ömrünce Cehennem ateşine götürecek günâhlar yapar. Bu kimse, ömrünün son günlerinde, Cennete götürecek iyilikler yaparak, Cennete gider","kaynak":null,"kisim":2,"madde":50,"sayfa":715},{"metin":"Sizden sonra, bir zemân gelecekdir. O zemânda bulunan müslimânların en sefîlleri, en aşağıları, müezzinlerdir","kaynak":"Künûz-üd-dekâık","kisim":2,"madde":52,"sayfa":723},{"metin":"Nikâhı herkese duyurunuz! Bunun için de, câmi’lerde yapınız ve defler çalınız!","kaynak":"Hadîka","kisim":2,"madde":52,"sayfa":726},{"metin":"Hâkimler rüşvet alarak haksız karâr verir. Adam öldürmek çoğalır. Gençler, ana babalarını, hısm akrabâsını aramaz, saymaz olur. Kur’ân-ı kerîm mizmârdan, ya’nî çalgı âletlerinden okunur. Tecvîd ile, güzel okuyanları, islâmiyyete uyan hâfızları dinlemeyip, mûsikî ile şarkı gibi okuyanları dinlerler.","kaynak":"Tergîb-üs-salât","kisim":2,"madde":52,"sayfa":727},{"metin":"Mizmârları kırmak için ve hınzırları öldürmek için gönderildim","kaynak":null,"kisim":2,"madde":52,"sayfa":728},{"metin":"Kur’ân-ı kerîmi arab şîvesi ile, onların sesi ile okuyunuz! Fâsıklar, şarkıcılar gibi okumayınız!","kaynak":null,"kisim":2,"madde":52,"sayfa":728},{"metin":"Ümmetimdeki münâfıkların çoğu, Kur’ân-ı kerîm okuyanlardan olacakdır","kaynak":null,"kisim":2,"madde":52,"sayfa":728},{"metin":"Kur’ân-ı kerîm, okuyanlarına, yâ şefâ’at edecek veyâ düşman olacakdır","kaynak":"Müslim","kisim":2,"madde":52,"sayfa":728},{"metin":"Kur’ân-ı kerîm okuyan çok kimse vardır ki, Kur’ân-ı kerîm, onlara la’net eder","kaynak":"Müslim","kisim":2,"madde":52,"sayfa":728},{"metin":"Şi’r, iyisi iyi olan, çirkini çirkin olan sözdür","kaynak":null,"kisim":2,"madde":52,"sayfa":730},{"metin":"Tetayyur eden ve tetayyur olunan ve kâhinlik yapan ve kâhine giden ve sihr, büyü yapan ve yapdıran ve bunlara inanan, bizden değildir. Kur’ân-ı kerîme inanmamışdır","kaynak":null,"kisim":2,"madde":53,"sayfa":739},{"metin":"O mektûbu kaldır. Yoksa, mektûbun acısını, kıyâmete kadar çekerler!","kaynak":null,"kisim":2,"madde":53,"sayfa":741},{"metin":"Yatarken Âyet-el kürsî okuyana, şeytân yaklaşamaz","kaynak":null,"kisim":2,"madde":53,"sayfa":741},{"metin":"Karşıki ağaca git, de ki, Allahın Peygamberi seni çağırıyor!","kaynak":null,"kisim":2,"madde":61,"sayfa":752},{"metin":"Yâ Bilâl “radıyallahü teâlâ anh”! Beni râhatlandır!","kaynak":null,"kisim":2,"madde":72,"sayfa":769},{"metin":"Îsâ aleyhisselâmın yapdığını yapmakda ben herkesden ilerideyim. Peygamberler “aleyhimüsselâm”, babaları bir olan kardeşler gibidirler. Anaları ayrıdır. Dinleri birdir","kaynak":null,"kisim":2,"madde":72,"sayfa":770},{"metin":"Küfrü açık bilinmiyen kimseye kâfir diyen, kâfir olur","kaynak":null,"kisim":2,"madde":73,"sayfa":771},{"metin":"Kolay şeyleri yapınız! İşlerinizi güçleşdirmeyiniz! Gücünüz yetdiği şeyleri yapınız! Allahü teâlâ, kolay olanları yapmanızı istiyor","kaynak":null,"kisim":2,"madde":73,"sayfa":772},{"metin":"Geceleri, Rabbimin ziyâfetindeyim. Beni doyuruyor ve içiriyor","kaynak":null,"kisim":2,"madde":73,"sayfa":772},{"metin":"Bir zemân gelecek ki, ümmetimde müslimânlığın yalnız adı kalacak. Mü’min olanlar, yalnız birkaç islâm âdetini yapacak. Îmânları kalmıyacak. Kur’ân-ı kerîm yalnız, okunacak. Emrlerinden, yasaklarından haberleri bile olmıyacak. Düşünceleri yalnız yiyip içmek olacak. Allahü teâlâyı unutacaklar. Yalnız paraya tapınacaklar. Kadınlara köle olacaklar. Az kazanmak ile kanâ’at etmiyecekler. Çok kazanınca doymıyacaklar","kaynak":null,"kisim":3,"madde":1,"sayfa":775},{"metin":"Bir zemân gelecek. Elbisenin rengi, zîneti solduğu gibi, yer yüzünde islâmiyyet de solup kalkacak. Öyle olacak ki, nemâz, oruc, hac, sadaka unutulacak. Kur’ân-ı kerîmden yer yüzünde bir âyet kalmıyacak","kaynak":null,"kisim":3,"madde":1,"sayfa":775},{"metin":"Bid’at işliyenlere büyük diyen, müslimânlığı yıkmağa yardım etmiş olur","kaynak":null,"kisim":3,"madde":1,"sayfa":776},{"metin":"Küçük şirkden korununuz!","kaynak":null,"kisim":3,"madde":2,"sayfa":778},{"metin":"Oruc benim için tutulur. Onun karşılığını ben veririm!","kaynak":null,"kisim":3,"madde":2,"sayfa":779},{"metin":"Yabancı kadınlara bakmak, gözlerin zinâsıdır. Onları tutmak, ellerin zinâsıdır. Onlara gitmek, ayakların zinâsıdır","kaynak":null,"kisim":3,"madde":2,"sayfa":781},{"metin":"Hac edenin geçmiş günâhları afv olur!","kaynak":null,"kisim":3,"madde":2,"sayfa":782},{"metin":"Dînin direği vera’dır","kaynak":null,"kisim":3,"madde":2,"sayfa":782},{"metin":"Mûsikî, zinâya yol açar","kaynak":null,"kisim":3,"madde":2,"sayfa":782},{"metin":"Müslimânlıkda, uğursuzluk ve hastalığın sağlam kimseye muhakkak geçmesi yokdur","kaynak":null,"kisim":3,"madde":2,"sayfa":782},{"metin":"Müslimân sihr yapamaz. Allah saklasın îmânı gitdikden sonra, sihri te’sîr eder.","kaynak":null,"kisim":3,"madde":2,"sayfa":782},{"metin":"Temîme ve Tivele şirkdir","kaynak":null,"kisim":3,"madde":2,"sayfa":784},{"metin":"İlâcların en iyisi Kur’ân-ı kerîmdir","kaynak":null,"kisim":3,"madde":2,"sayfa":784},{"metin":"Bile bile bir dirhem gümüş değerinde fâiz yimek, otuz zinâdan dahâ çok günâhdır","kaynak":null,"kisim":3,"madde":3,"sayfa":787},{"metin":"Elinin emeği, alnının teri ile yi, dînini satıp yime!","kaynak":null,"kisim":3,"madde":3,"sayfa":787},{"metin":"Halâle, harâma dikkat ederek çalışıp kazanan kimseyi, Allahü teâlâ çok sever","kaynak":null,"kisim":3,"madde":3,"sayfa":787},{"metin":"Bir dirhem gümüş kıymetinde harâm alan kimseyi, yirmibeşbin sene Cehennemde bırakacaklardır","kaynak":null,"kisim":3,"madde":3,"sayfa":787},{"metin":"Bir zemân gelecek ki, insanlar, yalnız malın, paranın gelmesini düşünüp, halâlini, harâmını düşünmiyecekler","kaynak":null,"kisim":3,"madde":3,"sayfa":787},{"metin":"İnsanın yidiklerinin en hayrlısı, iyisi, bileği ile kazanıp yidiğidir. Allahü teâlânın Peygamberi Dâvüd “aleyhisselâm” elinin emeği ile kazanıp yirdi","kaynak":"Buhârî","kisim":3,"madde":3,"sayfa":787},{"metin":"Bir müslimân, halâl kazanıp, kimseye muhtâc olmaz ve komşularına, akrabâsına yardım ederse, kıyâmet günü, ayın ondördü gibi parlak, nûrlu olacakdır","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"Doğru olan tüccâr, kıyâmetde sıddîklarla ve şehîdlerle berâber olacakdır","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"Allahü teâlâ, san’at sâhibi mü’mini sever","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"En halâl şey, san’at sâhibinin kazandığıdır","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"Ticâret yapınız! Rızkın onda dokuzu ticâretdedir","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"Kendini başkasından sadaka istiyecek hâle düşüreni, Allahü teâlâ yetmiş şeye muhtâc eder","kaynak":null,"kisim":3,"madde":3,"sayfa":788},{"metin":"Allahü teâlâ benim rızkımı, süngümün ucuna koymuşdur","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"Halâl kazanmak için sıkıntı çekenlere Cennet vâcib olur","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"Bana, tüccâr ol, mal topla diye emr olunmadı. Fekat, Rabbini tesbîh et ve ona secde et. Rabbine ölünciye kadar ibâdet et! diye emr olundu","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"Beş vakt nemâzı kıldıkdan sonra, çalışıp halâl kazanmak, her müslimâna farzdır","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"İnsanların iyisi, insanlara fâidesi olanlardır","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"Eshâbım için fakîrlik se’âdetdir. Âhır zemândaki ümmetim için, zenginlik se’âdetdir","kaynak":null,"kisim":3,"madde":3,"sayfa":789},{"metin":"Iyne satışı yaparsanız ve cihâdı terkedip, zirâ’at ile uğraşırsanız, Allahü teâlâ sizi zelîl eder. Dîninize dönmedikce, bu zilletden kurtulamazsınız!","kaynak":null,"kisim":3,"madde":12,"sayfa":826},{"metin":"Bir kimse gıdâ maddelerini alıp, pahâlı olup da satmak için kırk gün saklarsa, hepsini fakîrlere parasız dağıtsa, günâhını ödiyemez","kaynak":null,"kisim":3,"madde":15,"sayfa":840},{"metin":"Bir kimse gıdâ maddelerini kırk gün saklarsa, Allahü teâlâ ona darılır. O, Allahü teâlâyı saymamış olur","kaynak":null,"kisim":3,"madde":15,"sayfa":840},{"metin":"Bir kimse, hâricden gıdâ maddesi satın alıp, şehre getirir ve piyasaya göre satarsa, sadaka vermiş gibi sevâb kazanır veyâ köle âzâd etmiş gibi sevâb kazanır","kaynak":null,"kisim":3,"madde":15,"sayfa":840},{"metin":"Alışverişde vallahi böyledir, vallahi öyle değildir diye yemîn edenlere ve san’at sâhiblerinden, yarın gel, öbür gün gel diye sözünde durmıyanlara yazıklar olsun!","kaynak":null,"kisim":null,"madde":null,"sayfa":841},{"metin":"Malını yemîn ederek beğendiren kimseye kıyâmet günü merhamet edilmiyecek, acınmıyacakdır","kaynak":null,"kisim":3,"madde":15,"sayfa":841},{"metin":"Ticârete hıyânet karışınca, bereket gider","kaynak":null,"kisim":3,"madde":15,"sayfa":841},{"metin":"Lâ ilâhe illallah diyenler, dünyâyı dinden üstün tutmadıkca, Allahü teâlânın gadabından, azâbından kurtulurlar. Dîni bırakıp, dünyâya sarılırlarsa, bu kelime-i tevhîdi söyleyince, Allahü teâlâ, onlara, yalan söylüyorsun! buyurur","kaynak":null,"kisim":3,"madde":15,"sayfa":842},{"metin":"Alışverişde kolaylık gösterenlere, Allahü teâlâ, her işinde kolaylık gösterir","kaynak":null,"kisim":null,"madde":null,"sayfa":846},{"metin":"Kıyâmetde bir kimseyi hesâba çekerler ki, çok günâh işlemiş, hiç iyilik yapmamış. Sen dünyâda hiç iyilik yapmadın mı? derler. Hayır, yalnız çırağıma derdim ki, (Fakîr olan borcluları sıkışdırma! Ne zemân ellerine geçerse, o zemân vermelerini söyle. İstediklerini yine ver. Boş çevirme!) Allahü teâlâ buyuracak ki, (Ey kulum! Bugün sen fakîr, muhtâcsın! Sen dünyâda benim kullarıma acıdığın gibi, bugün biz de sana acırız). Onu afv eder.","kaynak":null,"kisim":3,"madde":16,"sayfa":846},{"metin":"Bir müslimâna, Allah rızâsı için ödünc veren kimseye, hergün için sadaka sevâbı verilir. Fakîrden, alacağını çabuk istemiyene, hergün için malın hepsini sadaka vermiş gibi sevâb verilir","kaynak":null,"kisim":3,"madde":16,"sayfa":846},{"metin":"Sadaka verilen her dirhem için on sevâb, ödünc verilen her dirhem için ise, onsekiz sevâb vardır. Çünki, borc, ihtiyâcı olana verilir. Sadaka belki, ihtiyâcı olmayanın eline düşebilir","kaynak":null,"kisim":3,"madde":16,"sayfa":846},{"metin":"En iyiniz, borcunu iyi ödiyeninizdir","kaynak":null,"kisim":3,"madde":16,"sayfa":846},{"metin":"Ödünc alan bir kimse, iyice ödemeği niyyet ederse, borcunu ödemesi için, melekler ona düâ eder","kaynak":null,"kisim":3,"madde":16,"sayfa":846},{"metin":"Melekler insanların amel defterlerini götürdükleri zemân, başında ve sonunda iyi iş yazılı ise, gün ortasında yapılanları ona bağışlarlar","kaynak":null,"kisim":3,"madde":17,"sayfa":848},{"metin":"Gündüz ve gece melekleri, sabâh ve akşam, gidip gelirken birbirleri ile karşılaşırlar. Hak teâlâ, [giden meleklere], kullarımı nasıl bırakdınız? buyurur. Yâ Rabbî! Nemâzda bulduk ve nemâz kılarken bırakdık, derler. Allahü teâlâ da, şâhid olun, onları afv etdim buyurur","kaynak":null,"kisim":3,"madde":17,"sayfa":848},{"metin":"Gâfiller arasında Allahü teâlâyı zikr eden kimse, kurumuş ağaçlar arasında bulunan yeşil fidân gibidir ve ölüler arasındaki cânlı gibidir ve harbde kaçanlar arasında, arslan gibi döğüşenler gibidir","kaynak":null,"kisim":3,"madde":17,"sayfa":848},{"metin":"Çarşıya giderken, lâ ilâhe illallah, vahde hü lâ şerîke leh, le hül mülkü ve le hül hamdü, yuhyî ve yümît, ve hüve hayyün lâ yemût, bi yedi-hil-hayr, ve hüve alâ külli şey’in kadîr diyen kimseye, iki milyon sevâb yazılır","kaynak":null,"kisim":3,"madde":17,"sayfa":848},{"metin":"Bir zemân gelir ki, o zemânın müslimânları, bugün sizin yapdığınız ibâdetlerin onda birini yaparsa, âhıretde azâbdan kurtulurlar","kaynak":null,"kisim":3,"madde":17,"sayfa":849},{"metin":"Dâr-ül-harbde, müslimân ile kâfir arasında fâiz yokdur","kaynak":null,"kisim":3,"madde":19,"sayfa":858},{"metin":"Kur’ân-ı kerîm okuyunuz. Fekat, bunu geçim vâsıtası yapmayınız!","kaynak":null,"kisim":3,"madde":21,"sayfa":872},{"metin":"Ezân okuyun. Ezân için ücret almayın!","kaynak":null,"kisim":3,"madde":21,"sayfa":872},{"metin":"Serhoş eden her içki şerâb gibi harâmdır","kaynak":"Müslim","kisim":3,"madde":22,"sayfa":880},{"metin":"Günâh işliyeni gören, eli ile mâni’ olsun. Buna gücü yetmezse, dili ile mâni’ olsun!","kaynak":null,"kisim":3,"madde":23,"sayfa":885},{"metin":"Fuhş söyliyenlerin Cennete girmeleri harâmdır","kaynak":null,"kisim":3,"madde":23,"sayfa":891},{"metin":"Allahü teâlâdan hayâ ediniz!","kaynak":"Berîka","kisim":3,"madde":23,"sayfa":891},{"metin":"Hayâ, îmândandır. Fuhş söylemek, cefâdandır. Îmân Cennete, cefâ Cehenneme götürür","kaynak":null,"kisim":3,"madde":23,"sayfa":891},{"metin":"Fuhş insanın lekesi, hayâ, zînetidir","kaynak":null,"kisim":3,"madde":23,"sayfa":891},{"metin":"Kul haklarını ödeyen, her nemâzdan sonra onbir ihlâs-i şerîf okuyan ve kâtilini afv ederek ölen Cennete girecekdir","kaynak":"Berîka","kisim":3,"madde":24,"sayfa":892},{"metin":"Ekber-i kebâir, birşeyi Allahü teâlâya ortak etmek, adam öldürmek, anaya, babaya karşı gelmek, yalancı şâhidlik yapmakdır","kaynak":"Buhârî","kisim":3,"madde":24,"sayfa":892},{"metin":"Bir kimse zulm ile öldürülürken, orada bulunmayınız! Orada bulunup da, kurtarmıyana la’net yağar","kaynak":null,"kisim":null,"madde":null,"sayfa":896},{"metin":"Ananın, babanın yüzüne merhamet ile bakana, makbûl hac sevâbı verilir","kaynak":"Berîka","kisim":3,"madde":26,"sayfa":900},{"metin":"Zikr ederek, kalblerinin yükünü hafîfletenlerin yolunda olunuz!","kaynak":null,"kisim":3,"madde":27,"sayfa":904},{"metin":"Onlar görüldüğü vakt, Allah hâtırlanır","kaynak":null,"kisim":3,"madde":27,"sayfa":904},{"metin":"Bir kimsenin havada uçduğunu ve deniz üzerinde yürüdüğünü yâhud ağzına ateş koyup yutduğunu görseniz, fekat islâmiyyete uymıyan bir iş yapsa, kerâmet sâhibiyim derse de, onu büyücü, yalancı, sapık ve insanları doğru yoldan sapdırıcı biliniz!","kaynak":null,"kisim":3,"madde":28,"sayfa":909},{"metin":"İlm üstâddan öğrenilir","kaynak":"Buhârî","kisim":3,"madde":28,"sayfa":909},{"metin":"Zemânların en hayrlısı benim zemânımdır","kaynak":null,"kisim":3,"madde":31,"sayfa":913},{"metin":"Yere ve göke sığmam. Fekat, mü’min kulumun kalbine sığarım","kaynak":null,"kisim":3,"madde":33,"sayfa":915},{"metin":"Câhiliyye zemânında iyi olanlarınız, müslimân olup din bilgilerini öğrenince de, en iyiniz olur!","kaynak":null,"kisim":3,"madde":38,"sayfa":924},{"metin":"Allahü teâlâ ile kul arasında, yetmişbin nûrdan perde ve yetmişbin zulmetden perde vardır","kaynak":null,"kisim":3,"madde":44,"sayfa":934},{"metin":"İnsan nemâza başlayınca, Allahü teâlâ ile kul arasında olan perde kalkar","kaynak":null,"kisim":3,"madde":51,"sayfa":956},{"metin":"Kişi sevdiği ile berâberdir","kaynak":null,"kisim":3,"madde":51,"sayfa":957},{"metin":"Siz dünyâ işlerinizi dahâ iyi bilirsiniz!","kaynak":null,"kisim":3,"madde":52,"sayfa":961},{"metin":"Nemâzda, kul ile Allahü teâlâ arasındaki perdeler kalkar","kaynak":null,"kisim":null,"madde":null,"sayfa":966},{"metin":"Âhıretde azâb görmez, dünyâ işlerinde, bana tâbi’ olan","kaynak":null,"kisim":null,"madde":null,"sayfa":970},{"metin":"Lezzetleri yıkan, eğlencelere son veren ölümü çok hâtırlayınız!","kaynak":null,"kisim":3,"madde":55,"sayfa":988},{"metin":"İnsanlar uykudadır, ölünce uyanırlar","kaynak":null,"kisim":3,"madde":55,"sayfa":989},{"metin":"Yanında Yasîn-i şerîf okunan hasta, suya doymuş olarak vefât eder ve doymuş olarak kabre girer","kaynak":null,"kisim":3,"madde":55,"sayfa":990},{"metin":"Ölüm hastası yanında, bir sûre okununca, her harfi için bir melek gelip, rûhun kolay çıkmasına düâ eder. Yıkanırken yanında bulunurlar. Cenâzesi ile birlikde giderler. Nemâzında bulunurlar. Gömülürken bulunurlar. Hep düâ ederler","kaynak":null,"kisim":3,"madde":55,"sayfa":991},{"metin":"Müslimân bir hasta yanında Yasîn-i şerîf okunursa, Rıdvân ismindeki melek Cennet şerbeti getirir. Suya doymuş olarak rûh teslîm eder. Doymuş olarak kabre girer. Suya ihtiyâcı olmaz.","kaynak":null,"kisim":3,"madde":55,"sayfa":991},{"metin":"Kulum, beni nasıl umarsa, onu öyle karşılarım. Öyle ise, benden hep iyilik bekleyiniz!","kaynak":null,"kisim":3,"madde":55,"sayfa":991},{"metin":"Allahü teâlâdan iyilik umarak cân veriniz!","kaynak":null,"kisim":3,"madde":55,"sayfa":991},{"metin":"Bir kimse, Allahü teâlâya kavuşmağı severse, Allahü teâlâ da ona kavuşmağı sever","kaynak":null,"kisim":3,"madde":55,"sayfa":992},{"metin":"Hastalığınızı tedâvî ediniz! Çünki, Allahü teâlâ, ölümden başka her hastalık için, devâ, ilâc yaratmışdır","kaynak":null,"kisim":3,"madde":55,"sayfa":992},{"metin":"Allahü teâlâyı unutarak, gafletle edilen düâ kabûl olmaz","kaynak":null,"kisim":3,"madde":55,"sayfa":992},{"metin":"Allahü teâlânın bir ni’met vermesini ve bunun devâmlı olmasını isteyen, Lâ havle velâ kuvvete illâ billah çok okusun!","kaynak":null,"kisim":3,"madde":55,"sayfa":993},{"metin":"Bu, Cennet hazînelerinden bir hazînedir!","kaynak":null,"kisim":3,"madde":55,"sayfa":993},{"metin":"Lâ havle velâ kuvvete okumak, doksandokuz derde devâdır. Bunların en hafîfi, hemmdir","kaynak":null,"kisim":3,"madde":55,"sayfa":993},{"metin":"Yağmur suyunu toplayıp, üzerine, Fâtiha-i şerîfe, Âyet-el-kürsi, İhlâs-ı şerîf ve Kul-e’ûzü sûreleri yetmişer kerre okunur. Bu sudan aralıksız yedi sabâh içenlerin hastalıkları, ağrıları zâil olur.","kaynak":null,"kisim":3,"madde":55,"sayfa":993},{"metin":"Yûnüs aleyhisselâm balığın karnında, Enbiyâ sûresinin 87. ci âyetini söyliyerek düâ etdi. [Düâsını kabûl eyledi ve kıyâmete kadar bunu okuyan mü’minlerin düâlarını kabûl edeceğini bildirdi.] Bir müslimân, bu âyet-i kerîmeyi okuyup düâ edince, Allahü teâlâ düâsını muhakkak kabûl eder","kaynak":null,"kisim":3,"madde":55,"sayfa":993},{"metin":"Âdem “aleyhisselâm” vefât edince, melekler Cennetden hanût ve kefen getirdiler. Su ve sedr yaprağı ile yıkadılar. Üçüncüsünde kâfûr koydular. Üç kefen ile kefenlediler. Nemâzını kıldılar. Lahd yapdılar. Defn etdiler. Sonra çocuklarına dönerek, ey Âdem oğulları! Ölülerinize böyle yapınız dediler","kaynak":null,"kisim":3,"madde":56,"sayfa":997},{"metin":"Cenâzeyi kırk adım taşıyanın kırk büyük günâhı afv olur.","kaynak":null,"kisim":3,"madde":58,"sayfa":1003},{"metin":"Cenâzeyi yüksek sesle ve ateş, ışık ve başka şeyler taşıyarak götürmeyiniz!","kaynak":"Künûz-üd-dekâık","kisim":3,"madde":58,"sayfa":1004},{"metin":"Bir hasta, lâ ilâhe illâ ente sübhâneke innî küntü minezzâlimîn kırk def’a okursa, şehîd olarak vefât eder. Şifâ bulursa, günâhları afv olur","kaynak":null,"kisim":3,"madde":58,"sayfa":1007},{"metin":"Anababasının veyâ ikisinden birinin kabrini her Cum’a günleri ziyâret edenin günâhları afv olur. Haklarını ödemiş olur","kaynak":null,"kisim":null,"madde":null,"sayfa":1008},{"metin":"Bir mü’minin kabrini ziyâret ederken, Allahümme innî es’elüke-bi-hurmet-i Muhammed aleyhisselâm en lâ tü’azzibe hâzelmeyyit derse, o meyyitin azâbı kıyâmete kadar ref’ olur","kaynak":null,"kisim":3,"madde":59,"sayfa":1008},{"metin":"Bir kimse, tanıdığının kabri yanından geçerken selâm verirse, meyyit bunu tanır ve selâmına cevâb verir","kaynak":null,"kisim":3,"madde":59,"sayfa":1008},{"metin":"Bir kimse, kabristândan geçerken, onbir kerre İhlâs sûresi okuyup sevâbını meyyitlere hediyye ederse, kendisine ölüler adedince sevâb verilir","kaynak":"İhyâ","kisim":3,"madde":59,"sayfa":1008},{"metin":"Ümmetimin yapdığı ibâdetlerin en kıymetlisi, Kur’ân-ı kerîmi, Mushafa bakarak okumakdır","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"Nemâzda okunan Kur’ân, nemâz dışında okunan Kur’ândan dahâ hayrlıdır","kaynak":"Mektûbât","kisim":3,"madde":59,"sayfa":1009},{"metin":"Kur’ân-ı kerîmi tecvîd bilgisine uyarak okuyunca, her harfine yirmi sevâb verilir. Tecvîde uymazsa, on sevâb verilir","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"İnsanın dinlediği bir âyet, kıyâmetde kendine nûr olur","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"Kur’ân-ı kerîm okuyunca, Allahü teâlânın rızâsını ve Cenneti isteyiniz! Dünyâlık istemeyiniz! Bir zemân gelir ki, hâfızlar, Kur’ân-ı kerîmi, insanlara yaklaşmak için vâsıta yaparlar","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"İnsanların en iyisi, hatmi bitirince, yeniden başlıyandır","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"Kur’ân-ı kerîm okuyanın ana-babası kâfir olsalar bile, azâbları hafîfler","kaynak":null,"kisim":3,"madde":59,"sayfa":1009},{"metin":"Kur’ân-ı kerîmi hatm edenin düâsı kabûl olunur","kaynak":"Künûz-üd-dekâık","kisim":3,"madde":59,"sayfa":1009},{"metin":"İbâdetlerin en iyisi, hatm okuyup, bitince yenisine başlamakdır","kaynak":null,"kisim":3,"madde":59,"sayfa":1010},{"metin":"Kur’ân-ı kerîmi tecvîde uygun okuyana şehîd sevâbı verilir","kaynak":"Künûz-üd-dekâık","kisim":3,"madde":59,"sayfa":1010},{"metin":"Üç mescidden başka mescidlere ziyâret için gidilmez","kaynak":null,"kisim":3,"madde":59,"sayfa":1010},{"metin":"Bir mü’min, tanıdığı bir mü’minin kabrine gelip selâm verince, onu tanır ve cevâb verir","kaynak":null,"kisim":3,"madde":60,"sayfa":1015},{"metin":"Ölünün mezârdaki hâli, imdâd diye bağıran, denize düşmüş kimseye benzer. Boğulmak üzere olan kimse, kendisini kurtaracak birini beklediği gibi, meyyit de, babasından, anasından, kardeşinden, arkadaşından gelecek bir düâyı gözler. Kendisine bir düâ gelince, dünyânın hepsi kendine verilmiş gibi sevinmekden dahâ çok sevinir. Allahü teâlâ, yaşıyanların düâları sebebi ile, ölülere dağlar gibi çok rahmet verir. Dirilerin de ölülere hediyyesi, onlar için düâ ve istigfâr etmekdir.","kaynak":null,"kisim":3,"madde":62,"sayfa":1018},{"metin":"Bir kimse, kendisi için veyâ başkası için yetmişbin aded Kelime-i tevhîd okursa, günâhları afv olur","kaynak":null,"kisim":3,"madde":62,"sayfa":1018},{"metin":"Bir kimse, başkası yerine oruc tutamaz ve nemâz kılamaz. Fekat, onun orucu ve nemâzı için fakîri doyurur","kaynak":null,"kisim":3,"madde":63,"sayfa":1019},{"metin":"Ferâiz ilmini öğrenmeğe çalışınız! Bu ilmi gençlere öğretiniz! Ferâiz ilmi, din bilgisinin yarısı demekdir. Ümmetimin en önce unutacağı, bırakacağı şey, bu ilm olacakdır","kaynak":null,"kisim":3,"madde":64,"sayfa":1025},{"metin":"Tâ’ûn, eski ümmetlere, azâb olarak gönderildi. Bu ümmet için şehîd olmağa sebebdir","kaynak":null,"kisim":3,"madde":67,"sayfa":1035},{"metin":"Düâ etmek, ibâdetdir","kaynak":null,"kisim":null,"madde":null,"sayfa":1036},{"metin":"Çalışmadan düâ eden, silâhsız harbe giden gibidir","kaynak":null,"kisim":null,"madde":null,"sayfa":1036},{"metin":"Bir kimse, mü’minler için, hergün yirmibeş kerre, istigfâr okursa, Allahü teâlâ, bu kimsenin kalbinden g›l ve hasedi ç›kar›r. ‹smi, Ebdâl ismleri aras›na yaz›l›r. Ona, bütün mü’minler adedince, sevâb yaz›l›r. K›yâmet günü, bütün mü’minler: Yâ Rabbî, bu kulun bizim için, istigfâr okurdu. Sen de onu afv eyle! derler","kaynak":null,"kisim":3,"madde":69,"sayfa":1037},{"metin":"Beşikden mezâra kadar ilm öğreniniz, çalışınız!","kaynak":null,"kisim":3,"madde":70,"sayfa":1045},{"metin":"Bilerek yapılan az bir ibâdet, bilmiyerek yapılan çok ibâdetden dahâ iyidir!","kaynak":null,"kisim":3,"madde":70,"sayfa":1045},{"metin":"İlm ikidir: Beden bilgisi, din bilgisi","kaynak":null,"kisim":3,"madde":70,"sayfa":1045},{"metin":"Efendim! Buraya, size hizmet etmeğe geldim. Bugüne kadar, bir hasta gelmedi. Boş oturdum, yiyip içip, râhat etdim. Artık gideyim","kaynak":null,"kisim":3,"madde":70,"sayfa":1046},{"metin":"Sen bilirsin! Eğer dahâ kalırsan, müsâfire hizmet etmek, ona ikrâm etmek, müslimânların başda gelen vazîfesidir. Gidersen de uğurlar olsun! Yalnız şunu bil ki, burada senelerce kalsan, sana kimse gelmez. Çünki, Eshâbım hasta olmaz! İslâm dîni, hasta olmamak yolunu göstermişdir. Eshâbım temizliğe çok dikkat eder. Acıkmadıkca birşey yimez ve sofradan, doymadan önce kalkar!","kaynak":null,"kisim":3,"madde":70,"sayfa":1046},{"metin":"İyi huyları temâmlamak, iyi ahlâkı dünyâya yaymak için gönderildim","kaynak":null,"kisim":3,"madde":70,"sayfa":1047},{"metin":"Îmânı yüksek olanınız, ahlâkı güzel olanınızdır!","kaynak":null,"kisim":3,"madde":70,"sayfa":1047},{"metin":"Allahü teâlânın, kalbime akıtdığı, doldurduğu feyzlerin, nûrların hepsini Ebû Bekrin kalbine akıtdım!","kaynak":null,"kisim":3,"madde":70,"sayfa":1051},{"metin":"Vera’ sâhibi ile birlikde oturmak ibâdetdir","kaynak":"Mektûbât","kisim":3,"madde":70,"sayfa":1053},{"metin":"Kur’ân-ı kerîmi kendi anladığına göre tefsîr eden kâfir olur","kaynak":null,"kisim":3,"madde":70,"sayfa":1054}]};
